QCU_T("es", "pathologie2", {
  "0": ["Normalmente, la dominancia cerebral se sitúa en el hemisferio:",["Izquierdo","Derecho","Derecho en los zurdos","Izquierdo solo en los diestros"],["En la gran mayoría de los individuos (incluida la mayoría de los zurdos), el hemisferio dominante para el lenguaje es el izquierdo.","El hemisferio derecho solo es dominante en una minoría.","La mayoría de los zurdos también tienen una dominancia izquierda.","La dominancia izquierda afecta también a la mayoría de los zurdos, no solo a los diestros."]],
  "1": ["La zona anterior del lenguaje está relacionada con:",["La producción del lenguaje (área de Broca)","La producción del lenguaje (área de Wernicke)","La comprensión del lenguaje hablado (área de Wernicke)","La comprensión del lenguaje hablado (área de Broca)"],["El área de Broca, frontal (anterior), es responsable de la producción/expresión del lenguaje.","Wernicke es posterior (temporal) y se refiere a la comprensión.","Es un área POSTERIOR, no anterior.","Broca gobierna la producción, no la comprensión."]],
  "2": ["Respecto al síndrome hipocinético-hipertónico, ¿qué proposición es correcta?",["Una disminución de la dopamina y un aumento de la acetilcolina","Un aumento de la dopamina y una disminución de la acetilcolina","Un aumento de la dopamina y de la acetilcolina","Una disminución de la dopamina y de la acetilcolina"],["El síndrome parkinsoniano asocia un déficit dopaminérgico nigroestriado y una hiperactividad colinérgica relativa.","Es el perfil inverso (más bien hipercinético/corea).","La dopamina está disminuida en el síndrome parkinsoniano.","La acetilcolina está relativamente aumentada, no disminuida."]],
  "3": ["En una lesión de la arteria cerebral media derecha:",["El paciente presenta una heminegligencia izquierda","El paciente presenta una heminegligencia derecha","El paciente presenta una afasia de Broca","El paciente presenta una hemianopsia lateral homónima derecha"],["La afectación parietal derecha (territorio ACM derecho) provoca una heminegligencia del hemicuerpo/hemicampo IZQUIERDO contralateral.","Falso: la negligencia es contralateral a la lesión, por tanto a la IZQUIERDA, no a la derecha.","Falso: la afasia de Broca depende de una afectación frontal IZQUIERDA (hemisferio dominante), no de una ACM derecha.","Falso: una afectación retrorrolándica derecha da una hemianopsia IZQUIERDA contralateral, no derecha."]],
  "4": ["La característica principal de todas las afasias transcorticales es:",["La repetición está preservada","La denominación no está preservada","La emisión y la comprensión están intactas","La repetición está abolida"],["Las afasias transcorticales se definen por una repetición CONSERVADA (fascículo arqueado intacto).","La denominación puede estar afectada, pero no es el rasgo distintivo de las transcorticales.","Según el tipo (motora/sensorial), la emisión O la comprensión está alterada.","Es al contrario: la repetición está preservada."]],
  "5": ["El sistema extrapiramidal es:",["Polisináptico e indirecto; rigidez de tipo plástico","Polisináptico y directo; rigidez de tipo plástico","Monosináptico e indirecto; rigidez de tipo plástico","Monosináptico y directo; rigidez de tipo espástico"],["El sistema extrapiramidal es polisináptico/indirecto; su lesión produce una rigidez plástica (en rueda dentada).","Falso: la vía extrapiramidal es INDIRECTA, no directa.","Falso: es POLIsináptica, no monosináptica.","Falso: monosináptico/directo con espasticidad describe la vía piramidal, no la extrapiramidal."]],
  "6": ["Los síndromes hipercinéticos son:",["Temblor, distonía, corea, balismo, mioclonías y atetosis","Acinesia, hipertonía, micrografía, corea, balismo y atetosis","Temblor, distonía, corea, acinesia, rigidez y bradicinesia","Bradicinesia, distonía, balismo, mioclonías, rigidez y atetosis"],["Los movimientos anormales hipercinéticos reúnen temblor, distonía, corea, balismo, mioclonías y atetosis.","Falso: la acinesia, la hipertonía y la micrografía son HIPOcinéticas (síndrome parkinsoniano), no hipercinéticas.","Falso: la acinesia, la rigidez y la bradicinesia pertenecen al síndrome HIPOcinético.","Falso: la bradicinesia y la rigidez son signos HIPOcinéticos y no pertenecen a las hipercinesias."]],
  "7": ["Respecto al síndrome de Brown-Séquard (hemisección medular), señale la opción INCORRECTA:",["Hipoalgesia y alteración de la sensibilidad térmica ipsilateral a la lesión","Una debilidad piramidal ipsilateral a la lesión y por debajo de ella","Sensibilidad vibratoria y posicional ipsilateral a la lesión","Hipoalgesia y alteración de la sensibilidad térmica contralateral a la lesión"],["INCORRECTO: capítulo 7 p. 13, en la hemisección medular la pérdida termoalgésica es CONTRALATERAL a la lesión (haz espinotalámico cruzado), nunca ipsilateral.","Verdadero: déficit motor piramidal homolateral por debajo de la lesión (Brown-Séquard).","Verdadero: afectación cordonal posterior homolateral.","Verdadero: la sensibilidad termoalgésica se pierde del lado opuesto."]],
  "8": ["La lesión medular anterior se caracteriza por:",["Una debilidad o parálisis de los miembros inferiores","La pérdida de la propiocepción","La pérdida de la sensibilidad vibratoria","Una pérdida aislada de la sensibilidad epicrítica"],["El síndrome medular anterior afecta a las vías motoras (y termoalgésicas), con déficit motor; la propiocepción (cordones posteriores) queda preservada.","La propiocepción (cordones posteriores) está PRESERVADA en la afectación anterior.","La sensibilidad vibratoria (cordones posteriores) está preservada.","La epicrítica depende de los cordones posteriores, respetados en la afectación anterior."]],
  "9": ["Los nervios espinales:",["Son nervios mixtos (sensitivomotores)","Son nervios puramente sensitivos","Son nervios puramente motores","Son nervios puramente vegetativos (autónomos)"],["Cada nervio espinal reúne una raíz motora ventral y una raíz sensitiva dorsal: es mixto.","Falso: son mixtos, y la raíz sensitiva es solo la dorsal (posterior).","Falso: son mixtos, y la raíz motora es solo la ventral (anterior).","Falso: son mixtos somáticos; el contingente vegetativo solo es una fracción de las fibras, no el conjunto."]],
  "10": ["Respecto a los dermatomas, señale la opción INCORRECTA:",["El dermatoma está inervado por la raíz espinal anterior (ventral, motora)","Cada dermatoma corresponde a un segmento medular y a un nervio espinal","El estudio de los dermatomas permite situar el nivel de una lesión medular","Un déficit sensitivo limitado a un dermatoma orienta hacia una afectación radicular"],["INCORRECTO: el dermatoma es una zona cutánea inervada por la raíz DORSAL (posterior, sensitiva), no por la raíz anterior motora.","Verdadero: un dermatoma = un nivel medular / un nervio espinal.","Verdadero: la topografía sensitiva localiza el nivel lesional.","Verdadero: un trastorno sensitivo sistematizado a un dermatoma evoca una lesión de la raíz correspondiente."]],
  "11": ["Respecto a la vía espinotalámica anterior:",["Se explora con un roce cutáneo (tacto protopático)","Se explora con un objeto puntiagudo (pinchazo, dolor)","Se explora con un test del sentido de posición (propiocepción)","Se explora con un test de discriminación táctil (tacto epicrítico)"],["La vía espinotalámica anterior vehicula el tacto grosero protopático; se explora con un roce de la piel.","Falso: el pinchazo prueba la vía espinotalámica LATERAL (dolor), no la anterior (tacto grosero).","Falso: la propiocepción depende de los cordones posteriores, no de la vía espinotalámica.","Falso: el tacto fino epicrítico depende de los cordones posteriores, no de la vía espinotalámica."]],
  "12": ["Marque la opción INCORRECTA en relación con las neuropatías:",["La neuropatía diabética es un ejemplo típico de radiculopatía","La polineuropatía afecta a varios troncos de forma simétrica y difusa","Las neuropatías comportan a menudo trastornos sensitivos (disestesias, hormigueos)","El síndrome de Guillain-Barré es un ejemplo de polirradiculoneuritis"],["INCORRECTO: la neuropatía diabética es una POLINEUROPATÍA distal y simétrica, no una radiculopatía (afectación de una raíz).","Verdadero: afectación bilateral, simétrica y generalizada.","Verdadero: las parestesias y las disestesias son frecuentes en ellas.","Verdadero: es una polirradiculoneuritis aguda (forma de polineuropatía)."]],
  "13": ["La siringomielia es un ejemplo típico de lesión medular:",["Centromedular","Anterior","Posterior","Hemimedular"],["La siringomielia es una cavidad centromedular; interrumpe las fibras espinotalámicas que cruzan por delante del canal (síndrome suspendido termoalgésico).","No es una afectación aislada del asta/arteria anterior.","Los cordones posteriores quedan respetados durante mucho tiempo.","La hemisección (Brown-Séquard) está lateralizada, no es central."]],
  "14": ["La pérdida de la capacidad de formular mentalmente y de expresar la secuencia de gestos necesarios para realizar una acción se llama:",["Apraxia ideatoria","Apraxia ideomotora","Apraxia constructiva","Apraxia del vestido"],["La apraxia ideatoria es la pérdida del plan conceptual y de la secuencia de los gestos de una acción compleja.","Falso: la ideomotora es la incapacidad de ejecutar un gesto a la orden, mientras el plan se conserva.","Falso: la constructiva afecta al ensamblaje espacial (dibujo, construcción), no a la secuencia de una acción.","Falso: la apraxia del vestido es un trastorno específico de la orientación de la ropa sobre el cuerpo, no de la secuencia gestual general."]],
  "15": ["Respecto al sistema reticular activador ascendente (SRAA), elija lo INCORRECTO:",["El SRAA forma parte de las zonas corticales que provocan los síndromes corticales topográficos","El SRAA mantiene la vigilia y la vigilancia activando la corteza cerebral","Su parte principal está en el tronco cerebral, con eferencias difusas hacia las estructuras corticales","Una afectación aguda puede provocar un síndrome confusional y un coma"],["INCORRECTO: el SRAA está situado en el TRONCO CEREBRAL (formación reticular), no es una estructura cortical.","Verdadero: es su función de activación cortical.","Verdadero: proyecciones difusas talamocorticales.","Verdadero: la afectación del SRAA altera la conciencia."]],
  "16": ["¿Cuál de estos elementos forma parte de los grados de alteración de la conciencia?",["El estupor","El estado confusional agudo (delirium)","El estado vegetativo","El mutismo acinético"],["El estupor es un grado de alteración de la vigilancia, situado entre la obnubilación y el coma: el paciente solo reacciona a estímulos vigorosos y repetidos.","Falso: la confusión es un trastorno de la calidad de la conciencia (contenido, atención) y no un grado de descenso de la vigilancia en el eje somnolencia-coma.","Falso: el estado vegetativo es un trastorno crónico de la conciencia con vigilia sin contenido (disociación vigilia/conciencia), no un grado progresivo de alteración de la vigilancia.","Falso: el mutismo acinético es un trastorno de la iniciación motora y verbal (afectación frontal/cingular), con vigilancia preservada, y no un nivel de alteración de la conciencia."]],
  "17": ["¿Cuál de los siguientes casos indica una alteración cerebral grave?",["La aparición de posturas reflejas en flexión o en extensión","La conservación del reflejo fotomotor bilateral","Una respuesta motora orientada al estímulo doloroso","Una puntuación de Glasgow medida en 15"],["Las posturas reflejas (decorticación, descerebración) indican una afectación grave, con sufrimiento del tronco cerebral.","Falso: un reflejo fotomotor conservado atestigua al contrario la integridad del tronco cerebral.","Falso: una respuesta orientada (localizadora) es tranquilizadora, mucho mejor que una postura refleja.","Falso: una puntuación de Glasgow de 15 corresponde a una vigilancia normal."]],
  "18": ["¿Cuál de las proposiciones describe mejor una red neuronal?",["Neuronas interconectadas que procesan la información de forma distribuida y plástica","Neuronas unidas en cadena que transmiten el impulso de un punto a otro","Neuronas de un mismo núcleo que comparten un único neurotransmisor","Neuronas de un área cortical dedicadas a una función única localizada"],["Una red neuronal es un conjunto interconectado que procesa la información de manera coordinada, distribuida y plástica (modificable por la experiencia).","Falso: describe una simple vía de conducción unidireccional, sin integración ni bucle de retroalimentación propios de una red.","Falso: describe una población neuroquímica homogénea, lo que no define la arquitectura interconectada de una red.","Falso: describe una localización funcional estricta, mientras que una red se basa en un procesamiento distribuido entre varias estructuras."]],
  "19": ["¿Durante qué periodo del desarrollo cerebral tiene lugar principalmente la migración neuronal?",["Semanas 12 a 24","Semanas 1 a 7","Semanas 27 a 40","Semanas 5 a 11"],["Capítulo 15 p. 12: «La migración neuronal se produce principalmente entre la 12.ª y la 24.ª semana de gestación», y la p. 18 recoge esa ventana en la cronología del desarrollo.","Capítulo 15 p. 18: antes de la 5.ª semana es la formación del tubo neural; la neurogénesis y después la migración vienen a continuación.","Capítulo 15 p. 18: «Final de la gestación-Infancia: diferenciación y sinaptogénesis (desde la 20.ª semana)». La migración ya ha terminado entonces.","Capítulo 15 p. 18: la semana 5.ª-20.ª es la de la NEUROGÉNESIS, la formación de las neuronas a partir de las células madre; la migración solo comienza en la 12.ª."]],
  "20": ["¿Qué significa la neuroplasticidad maladaptativa en el contexto de la neurorrehabilitación?",["Una remodelación neurológica poslesional que desembocaba en síntomas indeseables","Una pérdida de la capacidad del sistema nervioso central de reaccionar a una lesión","Una reorganización compensatoria imperfecta que favorece la recuperación funcional","Un refuerzo de las conexiones sanas que garantiza una mejor recuperación"],["La plasticidad maladaptativa es una reorganización mal orientada que produce efectos perjudiciales (espasticidad, dolores, esquemas anormales).","Falso: la plasticidad maladaptativa es una reacción (mal orientada), y no una ausencia de reactividad.","Falso: si favorece la recuperación, se denomina adaptativa, no maladaptativa.","Falso: eso describe la plasticidad ADAPTATIVA, en el extremo opuesto de la maladaptativa."]],
  "21": ["Respecto al desarrollo motor típico en los lactantes nacidos a término y sanos, ¿qué afirmación es la más correcta?",["El orden de adquisición de los hitos motores es estable, y la edad de aparición varía dentro de un margen normal","La edad de adquisición de cada hito es constante de un lactante sano a otro","El orden de los hitos motores varía libremente según el contexto cultural del niño","El ritmo del desarrollo motor es independiente de las estimulaciones ambientales"],["La secuencia de las adquisiciones es estable; solo la edad de aparición varía dentro de límites normales.","Falso: es la secuencia la que es constante, y la edad varía de un niño a otro.","Falso: la secuencia fundamental se conserva, y la cultura influye en la edad y no en el orden.","Falso: el entorno (estimulación, oportunidades) modula realmente el ritmo del desarrollo."]],
  "22": ["En un bebé prematuro nacido a las 26 semanas de edad gestacional, ¿qué competencia motora se espera (a la edad corregida correspondiente)?",["Puede apoyarse simétricamente sobre los codos y girar la cabeza","Puede voltearse de la espalda al vientre (DS → DP)","Puede voltearse del vientre a la espalda (DP → DS)","Se mantiene sentado sin apoyo"],["A la edad corregida esperada, el apoyo simétrico sobre los codos con rotación de la cabeza es la competencia coherente.","El volteo espalda-vientre es una adquisición más tardía.","El volteo vientre-espalda aparece también más tarde que el apoyo sobre los codos.","La sedestación autónoma (~6 meses de edad corregida) es mucho más tardía."]],
  "23": ["Se evalúa a un paciente que presenta una importante dificultad de control cefálico seis meses después de un ictus. ¿Qué sistema está más implicado?",["El sistema vestibuloespinal","El sistema reticuloespinal pontino","El sistema corticoespinal","El sistema tectoespinal"],["El control de la cabeza y la estabilización postural axial dependen en gran medida del sistema vestibuloespinal.","Participa en el tono postural, pero el control cefálico es más vestibuloespinal.","Gobierna sobre todo la motricidad fina distal, no la estabilización cefálica.","Interviene en los reflejos de orientación visuoauditiva, no en el mantenimiento postural de la cabeza."]],
  "24": ["¿Qué sistema proporciona la mayor estabilidad postural necesaria para los movimientos de alcance a nivel del tobillo y de la muñeca?",["El sistema corticorreticuloespinal","El sistema tectoespinal","El sistema corticoespinal medial","El sistema rubroespinal"],["La estabilidad postural anticipatoria de los movimientos de alcance se basa en la vía corticorreticuloespinal.","Papel limitado a la orientación refleja cabeza/ojos.","El contingente medial participa en el tronco, pero la estabilidad anticipatoria es corticorreticuloespinal.","Poco desarrollado en el ser humano; no asegura esa estabilidad postural."]],
  "25": ["¿Cuál es el objetivo principal del modelo biopsicosocial en neurorrehabilitación?",["Reducir las repercusiones funcionales de la lesión sobre la participación y la calidad de vida","Curar la patología subyacente y hacer regresar los síntomas clínicos","Estandarizar las intervenciones según únicamente los datos de evidencia disponibles","Centrarse en la corrección de la deficiencia estructural objetivamente medible"],["El modelo biopsicosocial busca la participación y la calidad de vida, más allá de la sola deficiencia.","Falso: ese es el objetivo del modelo biomédico, centrado en la enfermedad y no en la participación.","Falso: la práctica basada en la evidencia es una herramienta; el modelo integra también los factores personales y ambientales.","Falso: limitarse a la estructura corresponde al modelo biomédico, no al biopsicosocial."]],
  "26": ["Una mujer de 70 años ha sufrido un ictus isquémico. Tiene un buen apoyo familiar, caminaba a diario antes del ictus y presenta una diabetes controlada. ¿Qué afirmación es correcta respecto a su recuperación funcional?",["La diabetes sigue siendo un factor pronóstico desfavorable que hay que integrar en la rehabilitación","La edad de 70 años constituye por sí sola un freno a la neuroplasticidad residual","El apoyo familiar y la actividad física previa pesan poco en la recuperación","El buen equilibrio glucémico neutraliza el efecto de la diabetes sobre la recuperación"],["La diabetes altera la microcirculación y la plasticidad; es un factor pronóstico que hay que integrar incluso si está controlada.","Falso: la plasticidad persiste a cualquier edad; la edad sola no abole la recuperación.","Falso: son al contrario factores pronósticos favorables para la recuperación.","Falso: incluso controlada, la diabetes mantiene un efecto pronóstico; no queda totalmente anulado."]],
  "27": ["¿Cuál es la principal ventaja de la escala de Tardieu respecto a la escala de Ashworth modificada?",["Distingue el componente dependiente de la velocidad de la retracción fija","Cuantifica la retracción fija independientemente del tono","Gradúa la resistencia con un solo pase a velocidad lenta","Mide la fuerza voluntaria del músculo antagonista"],["Tardieu prueba el estiramiento a varias velocidades (V1, V2, V3): la diferencia de ángulo entre velocidad lenta y rápida aísla la espasticidad de la limitación muscular.","Falso: es precisamente la espasticidad dependiente de la velocidad lo que Tardieu aísla, pues la retracción se evalúa por el ángulo a velocidad lenta, no de forma independiente.","Falso: ese es el enfoque de Ashworth modificada (un pase); Tardieu impone varias velocidades de estiramiento.","Falso: Tardieu evalúa la reacción pasiva al estiramiento (tono), no la fuerza voluntaria, que corresponde a un balance muscular."]],
  "28": ["¿Cómo interpretar una mejora de 5 puntos cuando una escala tiene un MCID de 10 puntos?",["El cambio queda por debajo del umbral de relevancia clínica y puede deberse al error de medida","El cambio es estadísticamente significativo pero sin alcance clínico","El cambio alcanza un beneficio funcional perceptible por el paciente","El cambio supera el umbral mínimo y confirma la eficacia"],["Por debajo del MCID (5 < 10), el cambio no es clínicamente importante y puede atribuirse a la variabilidad de la medida.","Falso: el MCID no informa de la significación estadística, y nada indica aquí un efecto significativo.","Falso: es precisamente lo que mide el MCID, no alcanzado aquí (5 < 10).","Falso: 5 puntos es inferior al MCID de 10, por lo que el umbral no se ha superado."]],
  "29": ["¿Qué dispositivo es el más apropiado para un pie parético (marcha en estepaje)?",["Una órtesis suropédica antiequino (elevadora)","Una prótesis de miembro inferior","Una órtesis de postura nocturna antiequino","Una órtesis de estabilización de la rodilla"],["La órtesis elevadora (suropédica) suple el déficit de los flexores dorsales y corrige el pie caído en la fase oscilante.","Falso: una prótesis sustituye un segmento amputado; el pie parético está presente, hay que suplirlo funcionalmente.","Falso: previene la retracción en reposo pero no corrige el estepaje dinámico durante la marcha.","Falso: se dirige a una inestabilidad de la rodilla, no al déficit de flexores dorsales del tobillo responsable del estepaje."]],
  "30": ["¿Cuál es el principio fundamental de las terapias intensivas en neurorrehabilitación?",["Aumentar la repetición específica de la tarea para favorecer la neuroplasticidad","Privilegiar la pasividad y el reposo para limitar la fatiga central","Multiplicar ejercicios analíticos no orientados a la tarea","Repartir la misma carga en sesiones breves y espaciadas"],["La dosis elevada de repeticiones orientadas a la tarea es el motor de la reorganización neuroplástica poslesional.","Falso: es la intensidad activa, no el reposo, lo que induce la plasticidad.","Falso: la especificidad de la tarea, y no la simple repetición analítica, condiciona la transferencia funcional.","Falso: la terapia intensiva concentra la dosis; un espaciamiento excesivo reduce el efecto neuroplástico."]],
  "31": ["¿Qué estrategia inicial es la más apropiada para un paciente con una afasia expresiva crónica?",["Implantar una comunicación alternativa mediante pictogramas","Centrar el abordaje en la comprensión auditiva","Trabajar exclusivamente la repetición verbal forzada","Privilegiar la rehabilitación de la lectura en voz alta"],["En la afasia expresiva crónica, la comunicación aumentativa/alternativa (pictogramas) restaura un canal de expresión funcional.","Falso: la afectación es expresiva (producción); dirigirse solo a la comprensión no sostiene la expresión.","Falso: la repetición sola es insuficiente y frustrante en una afectación expresiva grave.","Falso: la lectura en voz alta moviliza la producción verbal deficitaria y no suple la expresión en la vida diaria."]],
  "32": ["¿Cuál es el objetivo principal de un exoesqueleto robótico en la rehabilitación de la marcha?",["Permitir un entrenamiento repetitivo e intensivo del patrón de marcha","Sostener pasivamente al paciente sin participación motora","Reforzar aisladamente la fuerza de los miembros inferiores","Corregir el equilibrio de pie estático del paciente"],["El exoesqueleto aporta una dosis elevada de repeticiones del ciclo de marcha manteniendo la participación activa del paciente.","Falso: el paciente debe permanecer activo; la asistencia no sustituye su implicación motora.","Falso: el objetivo es el reaprendizaje del patrón de marcha, no un fortalecimiento analítico aislado.","Falso: se dirige a la marcha dinámica repetida, no al control postural estático aislado."]],
  "33": ["¿Qué robot es el más apropiado para un paciente no autónomo para la marcha?",["Un exoesqueleto fijo que controla el patrón de marcha","Un exoesqueleto portátil controlado por el paciente","Un robot de efector terminal que guía los pies","Un robot de asistencia parcial activada por el esfuerzo"],["En el paciente no autónomo, el exoesqueleto fijo (sobre tapiz con suspensión) controla por completo el patrón de marcha con seguridad; el portátil supone autonomía, el efector terminal guía sobre todo las extremidades y el robot de asistencia parcial deja demasiada iniciativa al paciente.","Falso: el portátil supone cierta autonomía y capacidad de control, que aquí faltan; se prefiere el exoesqueleto fijo.","Falso: el efector terminal guía las extremidades pero controla menos el patrón global de marcha que el exoesqueleto fijo.","Falso: la asistencia parcial activada por el paciente exige una iniciativa motora residual, inadecuada en el no autónomo."]],
  "34": ["¿Qué intervención favorece más el uso del miembro superior afectado en un niño con parálisis cerebral?",["La terapia por restricción inducida del movimiento","La terapia por observación de la acción","La rehabilitación mediante realidad virtual","El entrenamiento bimanual sin restricción"],["La restricción inducida (CIMT) inmoviliza el miembro sano para forzar el uso del miembro afectado, con eficacia demostrada en la PC unilateral; la observación y la realidad virtual solo son complementos, y el entrenamiento bimanual sin restricción está menos dirigido al desuso.","Falso: la observación de la acción es un complemento útil pero menos eficaz por sí sola que la restricción inducida sobre el uso del miembro afectado.","Falso: la realidad virtual es una herramienta motivadora, pero menos demostrada específicamente que la restricción inducida en este punto.","Falso: el entrenamiento bimanual (HABIT) es beneficioso pero no fuerza el uso del miembro afectado tanto como la restricción inducida."]],
  "35": ["¿Cuál es el objetivo principal de las técnicas de neuromodulación?",["Modular la excitabilidad cortical para favorecer la plasticidad","Restaurar el movimiento mediante estimulación eléctrica de los músculos paralizados","Inhibir de forma duradera y completa la actividad del hemisferio lesionado","Producir una lesión dirigida de los circuitos hiperactivos por termocoagulación"],["La neuromodulación (EMTr, tDCS) ajusta la excitabilidad cortical, facilitando el hemisferio lesionado o inhibiendo el hemisferio sano, para potenciar la plasticidad y la recuperación.","Falso: eso describe la electroestimulación funcional (FES) periférica, que activa los músculos; la neuromodulación actúa sobre la excitabilidad de la corteza, no sobre la contracción muscular directa.","Falso: en el hemisferio lesionado se busca más bien facilitar la excitabilidad; la inhibición se dirige clásicamente al hemisferio sano hiperactivo, y nunca de forma duradera y completa.","Falso: eso corresponde a un procedimiento lesional (termolesión/neurotomía); la neuromodulación es no lesional y reversible."]],
  "36": ["Según el concepto Bobath, ¿qué intervención es la más apropiada?",["Facilitar la alineación postural y el control del tronco","Repetir intensivamente el movimiento funcional sin guía manual","Reforzar analíticamente la fuerza muscular contra resistencia máxima","Solicitar las reacciones de enderezamiento mediante la estimulación de los reflejos primitivos"],["El concepto Bobath busca normalizar el tono y facilitar la alineación postural y el control proximal del tronco, guiando el movimiento mediante puntos clave de control.","Falso: Bobath se basa en la facilitación manual por puntos clave y en la corrección del esquema, y no en la simple repetición autónoma no guiada.","Falso: Bobath privilegia la calidad del movimiento y la normalización del tono antes que un fortalecimiento analítico en fuerza, que puede aumentar la espasticidad.","Falso: Bobath busca inhibir los esquemas reflejos patológicos y los reflejos primitivos persistentes, no solicitarlos."]],
  "37": ["En pacientes con trastornos cognitivos, ¿qué estrategia es la MENOS apropiada?",["Aumentar los estímulos ambientales","Dar consignas simples y repetidas","Establecer rutinas previsibles","Fraccionar las tareas en etapas cortas"],["INADECUADO: multiplicar los estímulos sobrecarga la atención y desorienta; al contrario, se busca simplificar el entorno.","Estrategia apropiada: consignas simples y repetidas facilitan la comprensión.","Estrategia apropiada: la previsibilidad tranquiliza y apoya la memoria procedimental.","Estrategia apropiada: el fraccionamiento reduce la carga cognitiva."]],
  "38": ["Un hombre de 58 años consulta por un temblor de la mano derecha presente en reposo, que desaparece cuando coge un objeto. Observa una escritura que se ha vuelto pequeña, una cara poco expresiva y una marcha a pasos cortos. ¿Qué diagnóstico plantea en primer lugar?",["Una enfermedad de Parkinson","Un temblor esencial","Una corea","Una distonía cervical"],["Temblor de reposo asimétrico que desaparece con el movimiento + micrografía + hipomimia + marcha a pasos cortos = tríada/cuadro parkinsoniano típico.","El temblor esencial es postural/cinético (no de reposo) y no provoca hipomimia ni micrografía.","La corea corresponde a movimientos rápidos involuntarios irregulares, no a un temblor de reposo con lentitud.","La distonía produce posturas anormales sostenidas, sin temblor de reposo ni bradicinesia global."]],
  "39": ["¿Cuáles son los tres síntomas motores clásicos de la enfermedad de Parkinson?",["Temblor de reposo, bradicinesia y rigidez en rueda dentada","Temblor de acción, espasticidad e hiperreflexia","Corea, balismo y atetosis","Bradicinesia, ataxia y temblor intencional"],["La tríada parkinsoniana asocia temblor de reposo, bradicinesia/hipocinesia y rigidez plástica en rueda dentada.","El temblor de acción, la espasticidad y la hiperreflexia evocan una afectación piramidal/cerebelosa, no el síndrome parkinsoniano.","Son movimientos hipercinéticos, en el extremo opuesto del cuadro hipocinético parkinsoniano.","La ataxia y el temblor intencional son cerebelosos; no forman parte de la tríada parkinsoniana."]],
  "40": ["Respecto al temblor de la enfermedad de Parkinson, ¿qué afirmación es INCORRECTA?",["Aumenta durante los movimientos voluntarios y desaparece en reposo","Se debe a la ausencia de liberación de dopamina en el estriado","Es asimétrico al principio y después se generaliza","Es inicialmente distal, y evoca el gesto de «contar monedas»"],["INCORRECTO: el temblor parkinsoniano aparece EN REPOSO y desaparece con el movimiento y el sueño.","Verdadero: resulta del déficit dopaminérgico a nivel estriado.","Verdadero: inicio asimétrico y generalización posterior.","Verdadero: temblor distal en migaja («contar monedas»)."]],
  "41": ["La rigidez «en rueda dentada» de la enfermedad de Parkinson corresponde a:",["Una rigidez plástica en tubo de plomo sobre la que se superpone el temblor de reposo","Una hipertonía que cede bruscamente durante la extensión, en navaja","Una hipertonía elástica proporcional a la velocidad de estiramiento pasivo","Una resistencia oposicionista que aumenta con el esfuerzo del examinador"],["Según el curso, la rueda dentada = rigidez plástica (tubo de plomo) sobre la que se superpone el temblor de reposo; las demás opciones describen otros tipos de hipertonía.","Falso: el «muelle de navaja» es la espasticidad piramidal, no la rigidez parkinsoniana, que permanece homogénea.","Falso: la hipertonía elástica dependiente de la velocidad es la espasticidad (afectación piramidal), no la rigidez parkinsoniana.","Falso: esa resistencia oposicionista es la paratonía (Gegenhalten), de origen frontal, y no la rigidez parkinsoniana."]],
  "42": ["¿Cuál es la base fisiopatológica de la enfermedad de Parkinson?",["La pérdida de las neuronas dopaminérgicas de la sustancia negra con depósitos de alfa-sinucleína","La pérdida de las neuronas colinérgicas corticales con depósitos de proteína beta-amiloide","La degeneración de las neuronas estriatales ligada a una expansión de tripletes CAG","La desmielinización inflamatoria diseminada de la sustancia blanca central"],["La EP resulta de la degeneración dopaminérgica de la sustancia negra y de la acumulación de alfa-sinucleína (cuerpos de Lewy); las demás opciones corresponden a otras patologías.","Falso: el déficit colinérgico y las placas amiloides caracterizan la enfermedad de Alzheimer, no la enfermedad de Parkinson.","Falso: la afectación estriatal por expansión CAG (gen HTT) define la enfermedad de Huntington, no la enfermedad de Parkinson.","Falso: la desmielinización inflamatoria caracteriza la esclerosis múltiple, no la enfermedad de Parkinson."]],
  "43": ["Respecto a la epidemiología de la enfermedad de Parkinson, ¿qué proposición es correcta?",["Es la segunda enfermedad neurodegenerativa más frecuente tras la enfermedad de Alzheimer","Comienza típicamente antes de los 30 años en la mayoría de los casos","Es claramente más frecuente en la mujer","Es la enfermedad neurodegenerativa más frecuente, por delante del Alzheimer"],["La EP es la 2.ª enfermedad neurodegenerativa tras el Alzheimer, más frecuente en el hombre, con inicio típico entre los 50 y los 60 años.","La aparición típica es a los 50-60 años; solo del 5 al 10 % comienza antes de los 40 años.","Es al contrario más frecuente en el hombre.","El Alzheimer es la más frecuente; la EP viene en segundo lugar."]],
  "44": ["¿Qué elemento orienta claramente hacia una enfermedad de Parkinson idiopática más que hacia otro parkinsonismo?",["Una mejoría significativa de los síntomas con levodopa","Una ausencia total de respuesta a cualquier tratamiento dopaminérgico","Una evolución por brotes y remisiones","Una instauración brusca en unas horas"],["La buena respuesta a la levodopa es un argumento diagnóstico mayor de la EP idiopática (y ayuda a excluir los Parkinson-plus).","La ausencia de respuesta a la levodopa evoca más bien un parkinsonismo atípico (Parkinson-plus).","La evolución por brotes evoca la EM, no la EP (que es progresiva).","Una instauración brusca evoca una causa vascular, no la EP idiopática."]],
  "45": ["Un paciente parkinsoniano tratado a largo plazo con levodopa desarrolla movimientos involuntarios que aparecen en el momento en que el medicamento es más activo. ¿Cómo lo explica?",["Una discinesia de pico de dosis, complicación de la levodopa a largo plazo","Una acinesia de fin de dosis, que traduce una infradosificación dopaminérgica","Un efecto de una sobredosificación de anticolinérgicos asociados","Una distonía de periodo OFF, ligada a la falta de dopamina"],["La levodopa a largo plazo expone a las fluctuaciones (fenómeno ON-OFF) y a las discinesias de pico de dosis, que aparecen en el acmé del efecto dopaminérgico.","Falso: la acinesia de fin de dosis aparece cuando el efecto del medicamento SE AGOTA, no cuando es máximo; aquí los movimientos coinciden con el PICO de efecto.","Falso: el mecanismo implicado es dopaminérgico (pico de levodopa); un exceso de anticolinérgicos daría más bien confusión y signos atropínicos, no esos movimientos ajustados al acmé de la levodopa.","Falso: la distonía de periodo OFF aparece en fase de DÉFICIT dopaminérgico; en cambio, estos movimientos aparecen en el pico de EFECTO del tratamiento."]],
  "46": ["Entre estas causas de parkinsonismo, ¿cuál es un parkinsonismo SECUNDARIO (y no un Parkinson-plus)?",["El parkinsonismo inducido por los neurolépticos (antipsicóticos)","La parálisis supranuclear progresiva","La atrofia multisistémica","La demencia por cuerpos de Lewy"],["El parkinsonismo medicamentoso (neurolépticos, metoclopramida...) es un parkinsonismo secundario.","La PSP es un Parkinson-plus (parkinsonismo degenerativo primario).","La AMS es un Parkinson-plus degenerativo.","La demencia por cuerpos de Lewy forma parte de los síndromes Parkinson-plus."]],
  "47": ["Una paciente que toma antipsicóticos desde hace varios años presenta movimientos repetitivos de masticación, de protrusión de la lengua y de parpadeo. ¿Cómo califica ese trastorno?",["Una discinesia tardía","Un temblor esencial","Una mioclonía","Una atetosis"],["Las discinesias tardías (movimientos bucolinguofaciales repetitivos) resultan del uso prolongado de neurolépticos o de metoclopramida.","El temblor esencial es una oscilación rítmica postural, no movimientos bucolinguales repetitivos.","La mioclonía es una sacudida breve y brusca de un músculo, no un movimiento repetitivo sostenido de masticación.","La atetosis corresponde a movimientos de torsión lentos de las extremidades, distintos de los movimientos bucolinguales de las discinesias tardías."]],
  "48": ["¿Cuál es el trastorno del movimiento más frecuente, caracterizado por un temblor postural de las extremidades, de la cabeza (movimientos de afirmación/negación) y de la voz?",["El temblor esencial","El temblor de reposo parkinsoniano","La corea de Huntington","El balismo"],["El temblor esencial es el trastorno motor más frecuente: postural (± cinético), que afecta a las manos, a la cabeza (sí/no) y a la voz, con predisposición genética.","El temblor parkinsoniano aparece en reposo y se acompaña de bradicinesia, lo que no ocurre aquí.","La corea produce movimientos bruscos irregulares, no un temblor postural rítmico.","El balismo corresponde a movimientos amplios y violentos de proyección de un miembro, no a un temblor."]],
  "49": ["En el plano fisiopatológico, la corea se relaciona con:",["Una menor inhibición estriatal colinérgica o un exceso de actividad dopaminérgica","Un exceso de inhibición estriatal colinérgica del núcleo estriado","Un déficit dopaminérgico de la vía nigroestriada","Una lesión aislada del núcleo subtalámico contralateral"],["La corea resulta de una inhibición estriatal (acetilcolina) DISMINUIDA o de una hiperactividad dopaminérgica, que libera el freno sobre los movimientos.","Falso: es lo inverso, la corea corresponde a una inhibición estriatal colinérgica MENOR, no excesiva.","Falso: el déficit dopaminérgico nigroestriado produce un síndrome parkinsoniano hipocinético, no una corea hipercinética.","Falso: la lesión del núcleo subtalámico se asocia al balismo (movimientos amplios y violentos), y ese mecanismo no explica la corea de origen estriatal."]],
  "50": ["¿Cómo describiría el hemibalismo?",["Movimientos involuntarios amplios y violentos, de tipo «lanzamiento» del miembro, en un solo lado del cuerpo","Movimientos de torsión lentos y continuos de las extremidades","Sacudidas musculares breves y aisladas","Posturas anormales sostenidas por contracción prolongada"],["El balismo/hemibalismo corresponde a movimientos bruscos, amplios y violentos de proyección de los miembros, unilaterales.","Esa descripción corresponde a la atetosis, no al balismo.","Las sacudidas breves corresponden a las mioclonías.","Las posturas sostenidas definen la distonía."]],
  "51": ["Entre estos movimientos anormales, ¿cuál corresponde a una contracción breve e involuntaria (un espasmo) de un músculo o grupo muscular?",["La mioclonía","La atetosis","La distonía","El balismo"],["La mioclonía es una contracción breve, brusca e involuntaria de un músculo o grupo muscular.","La atetosis está hecha de movimientos de torsión lentos y constantes, no de sacudidas breves.","La distonía es una contracción sostenida que produce posturas anormales, no una sacudida breve.","El balismo es un movimiento amplio y violento de proyección, no una sacudida breve localizada."]],
  "52": ["Respecto a la enfermedad de Huntington, ¿qué proposición es correcta?",["Transmisión autosómica dominante por expansión de tripletes CAG","Transmisión autosómica recesiva por deleción del gen HTT","Transmisión ligada al X por mutación puntual del gen HTT","Afección adquirida por déficit dopaminérgico de la sustancia negra"],["El Huntington es autosómico dominante, ligado a la expansión CAG del gen HTT (huntingtina); al menos 36 repeticiones = enfermedad, con anticipación.","Falso: la transmisión es DOMINANTE y el mecanismo es una EXPANSIÓN CAG, no una deleción.","Falso: la transmisión es autosómica (no ligada al X) y el mecanismo es una expansión de tripletes, no una mutación puntual.","Falso: ese es el mecanismo de la enfermedad de Parkinson; el Huntington es una enfermedad genética hereditaria."]],
  "53": ["En el sistema extrapiramidal, ¿cuál es el papel respectivo de la dopamina y de la acetilcolina sobre el núcleo estriado?",["La dopamina inhibe el estriado y la acetilcolina intensifica el movimiento","La dopamina intensifica el movimiento y la acetilcolina inhibe el estriado","La dopamina inhibe el estriado, y la acetilcolina también","La dopamina intensifica el movimiento, y la acetilcolina también"],["Según el curso, la dopamina inhibe el núcleo estriado y la acetilcolina activa la intensificación de los movimientos; su desequilibrio genera los trastornos del movimiento.","Falso: los papeles están invertidos, pues es la dopamina la que inhibe el estriado y la acetilcolina la que intensifica el movimiento.","Falso: sus acciones son opuestas sobre el estriado, y la acetilcolina no es inhibidora como la dopamina.","Falso: la dopamina INHIBE el estriado y solo la acetilcolina intensifica el movimiento; sus acciones no son idénticas."]],
  "54": ["Un hombre mayor se cae hacia delante y se golpea la frente, lo que provoca una hiperextensión forzada del cuello. Presenta después un déficit motor de predominio en los miembros superiores (más que en los inferiores) con trastornos esfinterianos. ¿Qué síndrome medular plantea?",["Un síndrome centromedular","Un síndrome de Brown-Séquard","Un síndrome de la cola de caballo","Un síndrome medular posterior"],["La hiperextensión cervical del sujeto mayor es el mecanismo típico del síndrome centromedular: afectación motora de predominio en los miembros superiores y trastornos esfinterianos.","El Brown-Séquard (hemisección) produce un déficit disociado lateralizado, no una afectación de predominio en los miembros superiores.","La cola de caballo afecta a las raíces lumbosacras: déficit flácido de los miembros inferiores y anestesia en silla de montar, no los miembros superiores.","El síndrome posterior produce sobre todo un trastorno propioceptivo/vibratorio, no un déficit motor de predominio en los miembros superiores."]],
  "55": ["¿Cuál es el síndrome medular más frecuente y el de pronóstico generalmente más favorable?",["El síndrome centromedular","El síndrome de sección medular completa","El síndrome medular posterior","El síndrome de Brown-Séquard"],["Según el curso, el síndrome centromedular es el más frecuente y el de mejor pronóstico (aunque depende de la edad y de los antecedentes).","La sección completa es rara y de pronóstico grave (pérdida total por debajo de la lesión).","El síndrome posterior es al contrario el MENOS frecuente.","El Brown-Séquard es más raro y de origen sobre todo traumático."]],
  "56": ["En el síndrome de Brown-Séquard (hemisección medular), ¿cómo se reparten los déficits?",["Déficit motor y propioceptivo del lado de la lesión, y pérdida termoalgésica del lado opuesto","Déficit motor y termoalgésico del mismo lado que la lesión","Pérdida de todas las sensibilidades en los dos lados de forma simétrica","Pérdida propioceptiva contralateral y déficit motor contralateral"],["Ipsilateral: debilidad piramidal + pérdida vibratoria/posicional (cordones posteriores); contralateral: pérdida termoalgésica (haz espinotalámico cruzado).","La pérdida termoalgésica es CONTRALATERAL (las fibras espinotalámicas ya han cruzado).","El Brown-Séquard produce un déficit disociado y lateralizado, no simétrico.","El déficit motor y propioceptivo son IPSILATERALES en el Brown-Séquard."]],
  "57": ["El síndrome medular anterior corresponde la mayoría de las veces a:",["Un infarto en el territorio de la arteria espinal anterior","Una carencia de vitamina B12","Una hiperextensión cervical","Una oclusión de la arteria espinal posterior"],["El síndrome anterior (2/3 anteriores de la médula, con los cordones posteriores respetados) es el tipo de infarto medular más frecuente (arteria espinal anterior).","La carencia de B12 (degeneración combinada subaguda) afecta a los cordones posteriores → síndrome posterior.","La hiperextensión cervical es el mecanismo del síndrome CENTROMEDULAR.","La oclusión de la arteria espinal posterior produce un síndrome POSTERIOR."]],
  "58": ["¿Cuál es la característica clínica principal del síndrome medular posterior (afectación de los cordones dorsales)?",["Una pérdida de la propiocepción y de la sensibilidad vibratoria con ataxia y signo de Romberg","Una pérdida de la sensibilidad al dolor y a la temperatura con conservación del tacto fino","Una parálisis flácida de los cuatro miembros con abolición de los reflejos osteotendinosos","Una espasticidad con signo de Babinski e hiperreflexia por debajo de la lesión"],["Los cordones posteriores vehiculan la propiocepción, la vibración y el tacto fino: su afectación produce una ataxia propioceptiva con signo de Romberg, mientras la sensibilidad termoalgésica se conserva.","Falso: ese es el perfil del síndrome ANTERIOR (haces espinotalámicos); el síndrome posterior preserva al contrario la sensibilidad termoalgésica.","Falso: cuadro del shock espinal o de una afectación extensa; el síndrome posterior es ante todo sensitivo, sin tetraplejía flácida.","Falso: signos piramidales de una afectación de los cordones laterales (haz corticoespinal), no de los cordones posteriores, que producen un síndrome sensitivo."]],
  "59": ["Una paciente presenta una anestesia «en silla de montar» (periné, nalgas, cara interna de los muslos), trastornos vesicoesfinterianos y una debilidad flácida asimétrica de los miembros inferiores después de una voluminosa hernia discal lumbar. ¿Qué diagnóstico?",["Un síndrome de la cola de caballo","Un síndrome del cono medular","Un síndrome de Brown-Séquard","Un síndrome centromedular"],["Afectación de las raíces lumbosacras: anestesia en silla de montar, trastornos esfinterianos y déficit flácido asimétrico de los miembros inferiores = síndrome de la cola de caballo (urgencia quirúrgica).","Falso: el cono (afectación medular terminal) produce un déficit más bien simétrico con posibles signos piramidales (Babinski), no un déficit flácido asimétrico radicular.","Falso: el Brown-Séquard (hemisección medular) produce un déficit disociado lateralizado, no una anestesia en silla de montar bilateral.","Falso: el centromedular (a menudo cervical) predomina en los miembros superiores y respeta el periné."]],
  "60": ["¿Qué distingue clínicamente el síndrome del cono medular del síndrome de la cola de caballo?",["El cono puede acompañarse de un signo de Babinski, y la cola de caballo produce un déficit flácido","La cola de caballo produce un déficit simétrico y el cono un déficit asimétrico","El cono respeta la sensibilidad perineal y la cola de caballo la abole","La cola de caballo produce una espasticidad marcada y el cono un déficit flácido"],["El cono contiene todavía médula (motoneurona superior → Babinski posible); la cola de caballo solo está formada por raíces (motoneurona inferior → parálisis flácida, hipotonía).","Falso: es lo inverso: el cono produce un déficit más bien simétrico y la cola de caballo un déficit asimétrico radicular.","Falso: el cono también produce una anestesia en silla de montar; ambos pueden afectar a la sensibilidad perineal.","Falso: es lo inverso: la cola de caballo (raíces) produce un déficit FLÁCIDO, y el cono puede dar signos piramidales."]],
  "61": ["¿Cómo se caracteriza el «shock espinal» en la fase inicial de una lesión medular?",["Una parálisis flácida con arreflexia completa por debajo de la lesión, transitoria","Una espasticidad con hiperreflexia y signo de Babinski desde el principio","Un déficit sensitivo por debajo de la lesión aislado, sin afectación motora","Un déficit motor definitivo e irreversible por debajo de la lesión"],["El shock espinal asocia parálisis flácida y pérdida de los reflejos por debajo de la lesión; es transitorio (de unos días a 2-8 semanas), y la recuperación se produce en dirección descendente.","Falso: la espasticidad, la hiperreflexia y el Babinski aparecen DESPUÉS de la fase de shock espinal, no desde el principio.","Falso: el shock espinal comporta una parálisis flácida motora marcada, no solo un déficit sensitivo.","Falso: el shock espinal es transitorio y regresa; no prejuzga el carácter definitivo de las lesiones."]],
  "62": ["El shock neurogénico que complica una lesión medular alta se manifiesta por:",["Una hipotensión asociada a bradicardia, por pérdida del tono simpático","Una hipertensión con taquicardia","Una hipovolemia por hemorragia exteriorizada","Una fiebre elevada con taquicardia"],["La interrupción simpática (lesiones por encima de D4) provoca vasodilatación/hipotensión y predominio vagal → bradicardia: es el shock neurogénico.","Es lo inverso: el shock neurogénico produce hipotensión y bradicardia.","El mecanismo es la pérdida del tono vasomotor (distributivo/neurogénico), no una hemorragia.","El shock neurogénico se acompaña más bien de hipotermia y bradicardia."]],
  "63": ["Entre estas causas de lesión medular, ¿cuál es una causa INTRÍNSECA (no compresiva)?",["La carencia de vitamina B12","La hernia discal medial","La metástasis epidural","El hematoma epidural"],["Verdadero: la carencia de B12 (degeneración combinada subaguda) es una causa INTRÍNSECA que afecta a los cordones posteriores y laterales, sin compresión.","Falso: causa EXTRÍNSECA compresiva (compresión discal anterior), no una afectación intrínseca del parénquima.","Falso: causa EXTRÍNSECA compresiva (compresión extramedular), no una afectación intrínseca.","Falso: causa EXTRÍNSECA compresiva (colección extramedular), no una afectación intrínseca del tejido medular."]],
  "64": ["En la valoración de una lesión medular, ¿cómo se define el «nivel neurológico» de la lesión?",["El nivel más caudal en el que las funciones sensitivas y motoras siguen siendo normales","El nivel de la vértebra más deformada en la radiografía","El nivel más alto totalmente paralizado","El nivel en el que aparece el reflejo de Babinski"],["El nivel neurológico corresponde al segmento más bajo que conserva funciones motora y sensitiva normales.","El nivel esquelético (óseo) no corresponde necesariamente al nivel neurológico funcional.","Se toma como referencia el último nivel NORMAL, no el más alto afectado.","El Babinski indica una afectación piramidal pero no define el nivel neurológico."]],
  "65": ["Para explorar directamente la médula espinal y los ligamentos del raquis (y no solo las vértebras), ¿qué prueba es la de elección?",["La RM medular","La radiografía simple","La TC del raquis","La mielografía"],["Verdadero: la RM es la prueba de elección para visualizar directamente la médula, los ligamentos y los discos.","Falso: muestra las vértebras y las deformidades óseas, pero no visualiza la médula espinal.","Falso: la TC explora sobre todo el hueso (fracturas, corticales); la RM sigue siendo superior para la médula en sí.","Falso: prueba invasiva con contraste, ampliamente sustituida por la RM, que visualiza directamente la médula."]],
  "66": ["Una mujer de 35 años, dos semanas después de una infección respiratoria, presenta una debilidad de las piernas que asciende progresivamente hacia los brazos, con abolición de los reflejos osteotendinosos y parestesias de las extremidades. ¿Qué diagnóstico plantea?",["Un síndrome de Guillain-Barré","Una miastenia grave","Una mielitis transversa aguda","Una compresión medular aguda"],["Verdadero: debilidad simétrica ascendente posinfecciosa + arreflexia + parestesias = polirradiculoneuritis aguda (Guillain-Barré).","Falso: fatigabilidad fluctuante que mejora con el reposo, reflejos conservados, sin progresión ascendente ni parestesias.","Falso: afectación medular con nivel sensitivo y reflejos a menudo VIVOS (síndrome piramidal), no una arreflexia ascendente.","Falso: produce un nivel sensitivo neto y un síndrome piramidal por debajo de la lesión, no una arreflexia difusa ascendente."]],
  "67": ["¿Cómo se define el síndrome de Guillain-Barré?",["Una polirradiculoneuritis inflamatoria aguda autoinmune","Una desmielinización inflamatoria del sistema nervioso central","Una enfermedad degenerativa crónica de las motoneuronas","Un trastorno de la unión neuromuscular autoinmune"],["Verdadero: el SGB es una polirradiculoneuritis aguda autoinmune que ataca la mielina o el axón de los nervios PERIFÉRICOS.","Falso: eso es la esclerosis múltiple; el SGB afecta al sistema nervioso PERIFÉRICO, no al central.","Falso: eso describe la ELA; el SGB es un proceso inflamatorio AGUDO, no degenerativo crónico.","Falso: eso es la miastenia; el SGB afecta a las raíces y a los nervios periféricos, no a la placa motora."]],
  "68": ["¿Cuál es el factor desencadenante más frecuente de un síndrome de Guillain-Barré?",["Una infección respiratoria o digestiva reciente","Una infección urinaria baja reciente","Una primoinfección por VIH","Una reactivación de herpes labial"],["Verdadero: el SGB sigue la mayoría de las veces a una infección respiratoria o gastrointestinal (Campylobacter jejuni ++) en las semanas previas, por mimetismo molecular.","Falso: el antecedente típico es una infección respiratoria o digestiva; una cistitis no es el desencadenante clásico del SGB.","Falso: el VIH puede acompañarse de polirradiculoneuritis, pero el desencadenante más frecuente sigue siendo una infección respiratoria o digestiva reciente.","Falso: el VHS labial no es el factor predominante; es sobre todo una infección respiratoria o digestiva (Campylobacter, CMV, VEB) la que precede al SGB."]],
  "69": ["¿Cuál es la forma clínica más frecuente de síndrome de Guillain-Barré (en particular en Europa)?",["La AIDP (polineuropatía inflamatoria desmielinizante aguda)","La AMAN (neuropatía axonal motora aguda)","El síndrome de Miller-Fisher","La AMSAN (forma axonal motora y sensorial)"],["La AIDP, que afecta a la mielina, es la forma más frecuente en Europa.","La AMAN, axonal, es más rara y más grave.","El Miller-Fisher es una variante poco frecuente (oftalmoplejía, ataxia, arreflexia).","La AMSAN es una forma axonal rara y de pronóstico menos favorable."]],
  "70": ["El síndrome de Miller-Fisher, variante del SGB, asocia clásicamente:",["Una oftalmoplejía, una ataxia y una arreflexia","Una debilidad ascendente, una arreflexia y una afectación sensitiva distal","Una parálisis facial bilateral, una disfagia y una arreflexia","Una oftalmoplejía, una debilidad proximal y una hiperreflexia"],["La tríada del Miller-Fisher es oftalmoplejía + ataxia + arreflexia, asociada a los anticuerpos anti-GQ1b.","Falso: ese es el cuadro de la forma clásica (AIDP) del SGB, no del Miller-Fisher, que comienza por los nervios oculomotores.","Falso: eso evoca una afectación bulbar o una variante faringocervicobraquial, no la tríada del Miller-Fisher.","Falso: el Miller-Fisher comporta una arreflexia (y no una hiperreflexia) y una ataxia, no una debilidad proximal."]],
  "71": ["¿Qué característica de la debilidad ayuda a distinguir el síndrome de Guillain-Barré del botulismo?",["Una debilidad ascendente y simétrica de los miembros","Una debilidad descendente que comienza por los nervios craneales","Una debilidad estrictamente unilateral de un hemicuerpo","Una debilidad fluctuante que empeora con el esfuerzo"],["El SGB progresa de forma ascendente y simétrica (de las piernas hacia los brazos), al contrario de la parálisis descendente del botulismo.","Falso: esa es la parálisis descendente del botulismo, no del SGB, que es ascendente.","Falso: el SGB es típicamente simétrico; una afectación hemicorporal evoca una causa central.","Falso: la fatigabilidad fluctuante orienta hacia la miastenia, no hacia el SGB."]],
  "72": ["¿Qué resultado de la punción lumbar es característico del síndrome de Guillain-Barré?",["Una proteinorraquia elevada sin aumento de las células","Una pleocitosis marcada con proteinorraquia normal","Una hipoglucorraquia con hiperproteinorraquia","Un líquido xantocrómico rico en hematíes"],["El SGB produce una disociación albuminocitológica: proteinorraquia elevada con celularidad normal.","Falso: una reacción celular franca orienta hacia una causa infecciosa (poliomielitis, meningorradiculitis), no al SGB.","Falso: la hipoglucorraquia evoca una meningitis bacteriana, no el SGB, donde la glucorraquia es normal.","Falso: un LCR sanguinolento o xantocrómico evoca una hemorragia meníngea, no el SGB."]],
  "73": ["Respecto al tratamiento de la fase aguda del síndrome de Guillain-Barré, ¿qué proposición es correcta?",["Inmunoglobulinas IV O plasmaféresis, sin asociar ambas","Inmunoglobulinas IV Y plasmaféresis asociadas desde el principio","Corticoides en monoterapia como tratamiento de referencia","Plasmaféresis precedida de una corticoterapia sistemática"],["Las IGIV (0,4 g/kg/día durante 5 días) y la plasmaféresis tienen una eficacia equivalente; no se asocian ambas.","Falso: la combinación de ambas no aporta un beneficio adicional y no está recomendada.","Falso: los corticoides solos no han demostrado eficacia en el SGB.","Falso: asociar corticoides a la plasmaféresis no mejora el pronóstico y no está recomendado."]],
  "74": ["¿Cuál es la complicación más temida del síndrome de Guillain-Barré, que justifica una vigilancia estrecha?",["La insuficiencia respiratoria por afectación de los músculos respiratorios","Los trastornos del ritmo por disautonomía cardiaca","Las broncoaspiraciones por afectación de los músculos de la deglución","La embolia pulmonar por encamamiento prolongado"],["La afectación de los músculos respiratorios (20-30 % de los casos) es la principal causa de ingreso en cuidados intensivos; se vigila la capacidad vital.","Falso: la disautonomía puede producir arritmias y variaciones tensionales, pero la complicación vital principal sigue siendo respiratoria.","Falso: la afectación bulbar expone a las broncoaspiraciones, pero es la insuficiencia respiratoria la que compromete primero el pronóstico vital.","Falso: el decúbito expone a la enfermedad tromboembólica, pero no es la complicación más temida propia del SGB."]],
  "75": ["¿Qué se busca en el examen de los reflejos osteotendinosos durante un síndrome de Guillain-Barré?",["Una abolición o disminución de los reflejos (arreflexia)","Una viveza exagerada de los reflejos (hiperreflexia)","Una trepidación epileptoide del pie (clonus)","Reflejos normales y simétricos (sin anomalía)"],["La arreflexia osteotendinosa, precoz y difusa, es un signo cardinal del SGB (afectación periférica).","Falso: la hiperreflexia indica una afectación central/piramidal, no el SGB, que es periférico.","Falso: el clonus traduce una afectación piramidal, en el extremo opuesto del cuadro periférico del SGB.","Falso: el SGB se acompaña típicamente de una abolición de los reflejos, no de un examen normal."]],
  "76": ["¿Más allá de cuántas semanas de evolución se habla de polineuropatía inflamatoria desmielinizante crónica (CIDP) en lugar de SGB?",["Más allá de 8 semanas","Más allá de 2 semanas","Más allá de 4 semanas","Más allá de 16 semanas"],["Una progresión que persiste más allá de 8 semanas hace plantear una CIDP (forma crónica) en lugar de un SGB.","Falso: 2 semanas queda dentro de la fase de progresión aguda del SGB, que puede agravarse hasta 4 semanas.","Falso: 4 semanas corresponde al límite habitual de progresión del SGB, todavía no a la CIDP (8 semanas).","Falso: el umbral que se retiene para la CIDP es 8 semanas, y no 16."]],
  "77": ["Respecto al pronóstico del síndrome de Guillain-Barré, ¿qué proposición es la más correcta?",["Pronóstico globalmente favorable, con recuperación a menudo lenta a lo largo de varios meses","Pronóstico desfavorable, con evolución mortal en la mayoría de los casos","Recuperación habitual, completa y rápida en unos días","Curación constante, sin ninguna secuela residual"],["Alrededor del 80 % de los pacientes recuperan una buena función en 6-12 meses; secuelas en ~15 % de los casos y mortalidad ~5 % (complicaciones respiratorias).","Falso: el SGB es reversible y la mortalidad sigue siendo limitada (~5 %), sobre todo por complicaciones respiratorias.","Falso: la recuperación es real pero lenta, y se extiende a lo largo de varios meses o años.","Falso: alrededor del 15 % de los pacientes conservan secuelas (debilidad, fatiga, dolor neuropático)."]],
  "78": ["¿Cómo se define la esclerosis múltiple (EM)?",["Enfermedad inflamatoria desmielinizante crónica del sistema nervioso central","Polirradiculoneuritis desmielinizante aguda del sistema nervioso periférico","Enfermedad degenerativa crónica de los núcleos grises centrales","Afectación isquémica aguda focal del sistema nervioso central"],["La EM es una afectación inflamatoria desmielinizante crónica del SNC, que evoluciona por brotes (lesiones = «placas»); el SNP queda respetado.","Falso: eso describe el síndrome de Guillain-Barré (afectación periférica aguda), no la EM.","Falso: eso evoca una enfermedad extrapiramidal (Parkinson, Huntington), no la EM.","Falso: eso describe un ictus isquémico, sin relación con la desmielinización autoinmune de la EM."]],
  "79": ["En la esclerosis múltiple, ¿qué células productoras de mielina son la diana de la destrucción?",["Los oligodendrocitos del sistema nervioso central","Las células de Schwann del sistema nervioso periférico","Los astrocitos del sistema nervioso central","Las células microgliales del sistema nervioso central"],["La mielina del SNC la producen los oligodendrocitos: son ellos los destruidos en la EM (el SNP, mielinizado por las células de Schwann, queda respetado).","Las células de Schwann mielinizan el SNP, que no está afectado por la EM.","Los astrocitos proliferan (gliosis cicatricial) pero no producen mielina.","La microglía participa en la inflamación, pero no produce mielina."]],
  "80": ["¿Cuál es el perfil epidemiológico típico de la esclerosis múltiple?",["Adulto joven, predominio femenino, frecuencia creciente al alejarse del ecuador","Adulto joven, predominio masculino, frecuencia creciente al alejarse del ecuador","Sujeto mayor, predominio femenino, frecuencia creciente al alejarse del ecuador","Adulto joven, predominio femenino, frecuencia máxima en el ecuador"],["La EM comienza en el adulto joven (20-30 años), afecta más a las mujeres (≈ 3:1) y es más frecuente lejos del ecuador (relación con la vitamina D).","Falso: el predominio es femenino (≈ 3:1), no masculino; el resto del perfil es exacto.","Falso: la EM comienza en el adulto joven (20-30 años), no en el sujeto mayor.","Falso: la frecuencia aumenta al alejarse del ecuador, no es máxima en él."]],
  "81": ["Una mujer de 28 años presenta una disminución de la agudeza visual de un ojo instaurada en unos días, con dolor al mover los ojos y un escotoma central. ¿Qué manifestación, a menudo reveladora de EM, plantea?",["Una neuritis óptica retrobulbar","Una neuropatía óptica isquémica anterior aguda","Una papilitis edematosa de origen inflamatorio","Una retinopatía serosa central"],["La neuritis óptica retrobulbar (pérdida visual subaguda unilateral + dolor con la movilización ocular + escotoma central) es una manifestación frecuente y a menudo inaugural de EM; el fondo de ojo es normal al principio porque la lesión está por detrás del globo.","Falso: la NOIAA afecta al sujeto de más edad, produce una pérdida visual brusca e indolora con edema de papila y déficit altitudinal, sin dolor con la movilización ocular.","Falso: la papilitis produce un edema de papila visible en el fondo de ojo, mientras que la neuritis retrobulbar de la EM se acompaña típicamente de un fondo de ojo inicialmente normal.","Falso: la coriorretinopatía serosa central produce una pérdida visual con metamorfopsias, indolora, sin dolor con la movilización ocular ni afectación del nervio óptico."]],
  "82": ["¿En qué consiste el signo de Lhermitte, sugestivo de esclerosis múltiple?",["Una descarga eléctrica descendente desencadenada por la flexión del cuello","Una descarga facial desencadenada por el roce de la mejilla","Un dolor lumbar descendente desencadenado por la elevación de la pierna","Una contractura de la pantorrilla desencadenada por la dorsiflexión del pie"],["La flexión anterior del cuello desencadena una descarga eléctrica descendente: es el signo de Lhermitte (afectación de los cordones posteriores cervicales).","Falso: eso describe la zona gatillo de una neuralgia del trigémino, no el signo de Lhermitte (descarga raquídea a la flexión del cuello).","Falso: eso describe el signo de Lasègue de una radiculopatía, no el signo de Lhermitte (descarga a la flexión del cuello).","Falso: eso evoca un signo de irritación piramidal (clonus), no el signo de Lhermitte (descarga a la flexión del cuello)."]],
  "83": ["¿Por qué los síntomas de un paciente con EM pueden agravarse transitoriamente con el calor (fenómeno de Uhthoff)?",["Porque el calor agrava el bloqueo de conducción de los axones desmielinizados","Porque el calor acelera la conducción de los axones desmielinizados","Porque el calor desencadena un brote inflamatorio desmielinizante","Porque el calor provoca una pérdida axonal definitiva"],["La elevación térmica aumenta el bloqueo de conducción de las fibras desmielinizadas y agrava transitoriamente los síntomas (fatiga, pérdida visual...).","Falso: el calor ralentiza y bloquea la conducción de las fibras desmielinizadas, no la acelera.","Falso: el Uhthoff es un fenómeno funcional reversible, sin nueva lesión inflamatoria ni desmielinización.","Falso: el agravamiento es transitorio y puramente funcional, sin destrucción axonal definitiva."]],
  "84": ["¿Qué anomalía oculomotora es muy característica de la esclerosis múltiple?",["La oftalmoplejía internuclear (lesión del fascículo longitudinal medial)","Una parálisis aislada y completa del nervio motor oculomotor común (III)","Una parálisis aislada del nervio abducens (VI) con esotropía","Una parálisis de la función de la verticalidad de la mirada (síndrome de Parinaud)"],["La oftalmoplejía internuclear, por afectación del fascículo longitudinal medial, es muy sugestiva de EM, sobre todo si es bilateral en un sujeto joven: déficit de aducción de un ojo con nistagmo del ojo abductor.","Falso: una afectación troncular completa del III (con ptosis y midriasis) evoca un aneurisma o una herniación, no la lesión central del fascículo longitudinal medial de la EM.","Falso: la parálisis del VI produce un déficit de abducción aislado no específico (hipertensión intracraneal, microvascular), mientras que la oftalmoplejía internuclear afecta a la aducción por lesión del FLM.","Falso: el síndrome de Parinaud depende de una afectación de la región pretectal (tumor pineal), y no del fascículo longitudinal medial sugestivo de EM."]],
  "85": ["¿Cuál es la forma evolutiva de EM más frecuente al inicio de la enfermedad?",["La forma recurrente-remitente (brotes y remisiones)","La forma primaria progresiva desde el principio","La forma secundaria progresiva desde el principio","Una forma puramente asintomática permanente"],["La forma recurrente-remitente, hecha de brotes (> 24 h) que regresan total o parcialmente, es la más frecuente al inicio.","La forma primaria progresiva (declive continuo sin brotes) es más rara y afecta sobre todo a los inicios más tardíos.","La forma secundaria progresiva sucede a una forma recurrente-remitente, no es el modo de inicio.","La EM se vuelve sintomática; el hallazgo casual sigue siendo la excepción."]],
  "86": ["¿En qué se convierte con el tiempo una proporción importante de las EM inicialmente recurrentes-remitentes?",["Evolucionan hacia una forma secundariamente progresiva","Evolucionan hacia una forma primaria progresiva","Evolucionan hacia una forma recurrente aislada benigna","Evolucionan hacia una forma progresiva-recurrente"],["Alrededor del 40 % de las formas recurrentes-remitentes evolucionan hacia una forma secundariamente progresiva después de 6 a 10 años de evolución.","Falso: la forma primaria progresiva es progresiva desde el principio y no sigue a una fase recurrente-remitente.","Falso: la forma benigna sigue siendo recurrente-remitente con pocas secuelas, no es la evolución mayoritaria a largo plazo.","Falso: la forma progresiva-recurrente es progresiva desde el principio con brotes añadidos, no sucede a una fase recurrente-remitente."]],
  "87": ["¿En qué se basa el diagnóstico de esclerosis múltiple?",["En una diseminación de las lesiones en el espacio y en el tiempo del sistema nervioso central","En una diseminación de las lesiones limitada al espacio, en un momento dado del SNC","En una afectación única y persistente de una sola zona del sistema nervioso central","En una afectación exclusiva del sistema nervioso periférico, sin lesión central"],["El diagnóstico se basa en la diseminación espacial (≥ 2 zonas del SNC) y temporal (≥ 2 episodios), apoyada por la RM y el análisis del LCR; no existe una prueba única de referencia.","Falso: la diseminación espacial no basta, hace falta también la diseminación temporal (varios episodios en el tiempo).","Falso: una lesión única y fija no es una EM; el diagnóstico exige lesiones múltiples en el espacio y en el tiempo.","Falso: la EM es una afectación del SNC; una afectación puramente periférica orienta hacia una polineuropatía."]],
  "88": ["¿Qué anomalía del líquido cefalorraquídeo se encuentra típicamente en la esclerosis múltiple?",["La presencia de bandas oligoclonales de IgG","Una disociación albuminocitológica marcada","Una hipoglucorraquia profunda","Una pleocitosis de polimorfonucleares muy elevada"],["El LCR de la EM muestra bandas oligoclonales (síntesis intratecal de IgG), con pocas células y pocas proteínas.","La disociación albuminocitológica es característica del síndrome de Guillain-Barré, no de la EM.","La hipoglucorraquia evoca una meningitis bacteriana, no la EM.","El LCR de la EM es poco celular; una pleocitosis franca orienta a otra causa."]],
  "89": ["En el plano fisiopatológico, ¿cuál es el efecto de la desmielinización sobre la conducción nerviosa en la EM?",["Una ralentización, incluso un bloqueo, de la conducción a lo largo del axón","Una aceleración de la conducción a lo largo del axón desmielinizado","Una degeneración axonal primaria que precede a la pérdida de mielina","Una afectación del cuerpo celular de la motoneurona, sin afectar la vaina"],["La pérdida de mielina suprime la conducción saltatoria y ralentiza fuertemente (o incluso bloquea) la conducción a lo largo del axón.","Falso: la pérdida de mielina ralentiza la conducción (pérdida de la conducción saltatoria), no la acelera.","Falso: la afectación es primero desmielinizante; la pérdida axonal es secundaria y más tardía.","Falso: la EM afecta a la vaina de mielina; la afectación primaria del cuerpo de la motoneurona caracteriza la ELA."]],
  "90": ["Respecto al tratamiento de la esclerosis múltiple, ¿qué proposición es correcta?",["El brote se trata con corticoides a dosis altas y los tratamientos de fondo modifican la evolución sin curar","El brote se trata con corticoides a dosis altas y los tratamientos de fondo curan definitivamente","El brote no se trata y solo los tratamientos de fondo actúan sobre los síntomas agudos","El brote se trata con corticoides a dosis altas pero ningún tratamiento modifica la evolución"],["No existe un tratamiento curativo: el brote se trata con bolos de corticoides, y los tratamientos de fondo reducen la actividad de la enfermedad sin erradicarla.","Falso: los tratamientos de fondo ralentizan la evolución pero no curan la EM, que sigue sin tratamiento curativo.","Falso: el brote sí se trata con bolos de corticoides; los tratamientos de fondo actúan sobre la evolución, no sobre el brote agudo.","Falso: los tratamientos de fondo sí modifican la evolución (reducción de los brotes y de la actividad de la enfermedad)."]],
  "91": ["La esclerosis lateral amiotrófica (ELA) se caracteriza por:",["Una afectación combinada de la primera y de la segunda motoneurona, sin déficit sensitivo","Una afectación aislada de la segunda motoneurona, sin ningún signo piramidal","Una afectación motora combinada que evoluciona por brotes y remisiones","Una afectación sensitivomotora del sistema nervioso periférico"],["La ELA degenera las motoneuronas superior E inferior: amiotrofia y fasciculaciones (2.ª MN) más espasticidad y Babinski (1.ª MN), y la sensibilidad queda respetada.","Falso: la ELA asocia 1.ª y 2.ª motoneurona; una afectación puramente periférica sin signo piramidal no es una ELA.","Falso: la ELA es degenerativa y progresiva; la evolución por brotes y remisiones caracteriza la EM.","Falso: la ELA es una afectación motora pura de las motoneuronas; la sensibilidad queda típicamente respetada."]],
  "92": ["¿Cuál es la distribución aproximada de los ictus según su mecanismo?",["Alrededor del 85 % de ictus isquémicos y el 15 % de ictus hemorrágicos","Alrededor del 65 % de ictus isquémicos y el 35 % de ictus hemorrágicos","Alrededor del 50 % de ictus isquémicos y el 50 % de ictus hemorrágicos","Alrededor del 15 % de ictus isquémicos y el 85 % de ictus hemorrágicos"],["La gran mayoría de los ictus son isquémicos (~85 %); los hemorrágicos representan alrededor del 15 %.","Falso: la proporción de hemorrágicos está sobrestimada; los isquémicos rondan el 85 % y los hemorrágicos el 15 %.","Falso: los dos mecanismos no están equilibrados; los isquémicos son claramente mayoritarios (~85 %).","Falso: es lo inverso, los isquémicos dominan ampliamente (~85 % frente a ~15 %)."]],
  "93": ["¿Qué diferencia un accidente isquémico transitorio (AIT) de un infarto cerebral establecido?",["El AIT regresa espontáneamente sin lesión, y el infarto deja un déficit duradero con lesión","El AIT deja una lesión definitiva, y el infarto regresa sin secuela","El AIT dura más de 24 horas, y el infarto menos de una hora","El AIT afecta a la sustancia blanca, y el infarto a la sustancia gris"],["El AIT es un déficit isquémico transitorio que regresa sin lesión establecida; el infarto corresponde a una isquemia definitiva con lesión visible y déficit persistente.","Falso: es lo inverso, el AIT regresa sin lesión y el infarto deja una lesión y un déficit duraderos.","Falso: el AIT es breve y regresivo, y el infarto corresponde a una afectación prolongada y establecida, no al contrario.","Falso: la distinción se basa en la reversibilidad y en la ausencia de lesión (AIT) frente a una lesión establecida (infarto), no en la localización tisular."]],
  "94": ["Un paciente presenta de forma brusca una hemiplejía de la cara y del miembro superior derechos, que respeta relativamente el miembro inferior, asociada a un trastorno del lenguaje. ¿Qué territorio arterial está afectado con mayor probabilidad?",["La arteria cerebral media izquierda","La arteria cerebral anterior izquierda","La arteria cerebral posterior derecha","La arteria cerebelosa posteroinferior (PICA)"],["El déficit faciobraquial contralateral predominante + afasia orienta hacia la arteria cerebral media del hemisferio dominante (izquierdo).","La afectación de la arteria cerebral anterior predomina en el miembro INFERIOR (crural), no en el miembro superior ni en la cara.","La arteria cerebral posterior produce sobre todo una hemianopsia, no una hemiplejía faciobraquial con afasia.","La PICA produce un síndrome de Wallenberg/cerebeloso, no este cuadro hemisférico."]],
  "95": ["¿Cuál es el cuadro motor característico de un infarto de la arteria cerebral media?",["Una hemiplejía contralateral de predominio faciobraquial","Una hemiplejía contralateral de predominio crural","Una hemiplejía homolateral de predominio braquial","Una diplejía facial aislada sin déficit de los miembros"],["La arteria cerebral media irriga la zona motora de la cara y del miembro superior: el déficit contralateral predomina ahí, y el miembro inferior queda relativamente respetado.","Falso: el predominio en el miembro inferior (crural) evoca la arteria cerebral ANTERIOR, no la media.","Falso: el déficit de un ictus silviano es CONTRALATERAL a la lesión, nunca homolateral.","Falso: el ictus silviano asocia un déficit faciobraquial; una afectación facial aislada bilateral no es un cuadro silviano."]],
  "96": ["Cuando un infarto de la arteria cerebral media afecta al hemisferio NO dominante, ¿qué trastorno puede observarse?",["Una heminegligencia con anosognosia del déficit","Una afasia de Broca con agrafía","Una apraxia ideomotora con alexia","Una acalculia con agnosia digital"],["La afectación parietal del hemisferio no dominante produce una heminegligencia (omisión del campo contralateral) y una anosognosia (desconocimiento del déficit).","Falso: la afasia depende del hemisferio DOMINANTE (la mayoría de las veces izquierdo), no del no dominante.","Falso: la apraxia ideomotora y la alexia se vinculan al hemisferio DOMINANTE, no al no dominante.","Falso: esos signos (síndrome de Gerstmann) dependen del hemisferio DOMINANTE, no del no dominante."]],
  "97": ["¿Qué cuadro evoca una afectación de la arteria cerebral anterior?",["Un déficit contralateral de predominio en el miembro inferior con trastornos del comportamiento","Un déficit contralateral de predominio en la cara y en el miembro superior","Un déficit contralateral limitado a una hemianopsia lateral homónima","Un déficit contralateral asociado a una amaurosis homolateral"],["La arteria cerebral anterior irriga la cara interna del hemisferio (zona del miembro inferior): déficit crural contralateral y trastornos conductuales (apatía, desinhibición).","Falso: el predominio faciobraquial es propio de la arteria cerebral MEDIA, no de la anterior.","Falso: la hemianopsia lateral homónima depende de la arteria cerebral POSTERIOR, no de la anterior.","Falso: la asociación déficit + amaurosis homolateral evoca la carótida interna (arteria oftálmica), no la cerebral anterior."]],
  "98": ["Una oclusión de la arteria cerebral posterior se manifiesta típicamente por:",["Una hemianopsia lateral homónima contralateral","Una hemiplejía crural contralateral aislada","Una amaurosis fugaz monocular homolateral","Una hemiplejía faciobraquial contralateral aislada"],["La arteria cerebral posterior irriga la corteza occipital: su oclusión produce una hemianopsia lateral homónima contralateral, con posible respeto macular.","Falso: el déficit crural aislado evoca la arteria cerebral ANTERIOR, no la posterior.","Falso: la amaurosis fugaz monocular depende de la arteria oftálmica (carótida interna), no de la cerebral posterior.","Falso: el déficit faciobraquial depende de la arteria cerebral MEDIA, no de la posterior."]],
  "99": ["Los trastornos del lenguaje (afasia de Broca o de Wernicke) durante un ictus traducen una afectación:",["Del hemisferio dominante, izquierdo en el diestro","Del hemisferio no dominante, derecho en el diestro","Del lóbulo occipital del hemisferio dominante","Del tronco cerebral, a nivel protuberancial"],["El lenguaje está lateralizado en el hemisferio dominante, izquierdo en la práctica totalidad de los diestros: su afectación genera la afasia. A la derecha (no dominante): heminegligencia; lóbulo occipital: hemianopsia; tronco: afectación de los pares craneales.","Falso: el hemisferio no dominante (derecho en el diestro) produce heminegligencia y trastornos visuoespaciales, no afasia.","Falso: el lóbulo occipital gobierna la visión; su afectación produce una hemianopsia, no una afasia.","Falso: la afectación protuberancial afecta a las vías largas y a los pares craneales (diplopía, parálisis facial), no al lenguaje cortical."]],
  "100": ["¿Qué es un infarto lacunar?",["Un pequeño infarto profundo por oclusión de una arteria perforante","Un infarto cortical por oclusión de una arteria cerebral media","Un infarto de unión por bajo flujo entre dos territorios","Un infarto hemorrágico por transformación de un émbolo proximal"],["El infarto lacunar es una pequeña lesión profunda (< 1,5 cm) por oclusión de una arteria perforante, que produce un síndrome lacunar (p. ej. hemiparesia motora pura).","Falso: la oclusión silviana produce un infarto cortical extenso (silviano), no una laguna profunda de pequeño tamaño.","Falso: el infarto de unión (watershed) resulta de un bajo flujo en los confines de dos territorios, mecanismo distinto de la oclusión perforante.","Falso: la transformación hemorrágica afecta sobre todo a los grandes infartos embólicos, no a la laguna perforante."]],
  "101": ["¿Qué cardiopatía es una causa mayor de ictus isquémico cardioembólico?",["La fibrilación auricular","El foramen oval permeable","La hipertrofia ventricular izquierda","El bloqueo auriculoventricular completo"],["La fibrilación auricular favorece los trombos de la aurícula izquierda, embolígenos: es la primera causa de ictus cardioembólico (de ahí la anticoagulación).","Falso: el foramen oval permeable puede producir una embolia paradójica pero sigue siendo una causa menor y controvertida, no la causa mayor.","Falso: la hipertrofia ventricular izquierda es un marcador de riesgo vascular pero no es una fuente embolígena directa.","Falso: el bloqueo auriculoventricular expone a síncopes por bradicardia, no a la formación de trombos embolígenos."]],
  "102": ["En el manejo de un ictus isquémico, ¿qué significa el principio «time is brain»?",["La revascularización solo es útil dentro de una ventana de tiempo limitada","La fibrinólisis sigue siendo eficaz sea cual sea el tiempo transcurrido","El área de penumbra se pierde definitivamente desde la oclusión","El manejo tensional tiene prioridad sobre la reperfusión"],["Capítulo 2 p. 33: «útil solo dentro de un plazo: < 6 horas para la fibrinólisis intravenosa, < 12 horas para la revascularización». Más allá, el riesgo hemorrágico supera el beneficio.","Falso: más allá de la ventana terapéutica, el beneficio desaparece y el riesgo hemorrágico predomina.","Falso: la penumbra todavía es salvable durante un tiempo limitado, lo que justifica precisamente la urgencia de revascularizar.","Falso: es la reperfusión precoz lo que constituye el objetivo central, y el manejo tensional solo es una medida asociada."]],
  "103": ["En prevención secundaria de un ictus isquémico, ¿qué tratamiento corresponde a cada mecanismo?",["Antiagregación si es aterotrombótico, anticoagulación si es cardioembólico","Anticoagulación si es aterotrombótico, antiagregación si es cardioembólico","Anticoagulación si es aterotrombótico, anticoagulación si es cardioembólico","Antiagregación si es aterotrombótico, antiagregación si es cardioembólico"],["La aterotrombosis requiere antiagregación plaquetaria; la causa cardioembólica (p. ej. fibrilación auricular) requiere anticoagulación.","Falso: es lo inverso, la aterotrombosis requiere antiagregación y la cardioembolia anticoagulación.","Falso: el origen aterotrombótico se trata con antiagregante, no con anticoagulante.","Falso: la causa cardioembólica (p. ej. fibrilación auricular) requiere anticoagulación, no un antiagregante."]],
  "104": ["Ante una estenosis ateromatosa grave (> 70 %) de la carótida interna sintomática, ¿qué opción puede proponerse?",["Una endarterectomía carotídea","Una angioplastia carotídea sin antiagregante","Una anticoagulación curativa a largo plazo","Un bypass extraintracraneal sistemático"],["Una estenosis carotídea grave (> 70 %) sintomática requiere una endarterectomía (extirpación de la placa) para prevenir la recidiva.","Falso: la angioplastia con stent es una alternativa posible, pero siempre bajo antiagregación, nunca sin ella.","Falso: la estenosis ateromatosa requiere antiagregación y cirugía, no una anticoagulación curativa.","Falso: el bypass extraintracraneal no ha demostrado su beneficio y no es la opción de referencia aquí."]],
  "105": ["¿Cuál es la causa más frecuente de hemorragia subaracnoidea no traumática?",["La rotura de un aneurisma arterial intracraneal","La rotura de una malformación arteriovenosa","Un sangrado de angiopatía amiloide cerebral","La rotura de una arteria perforante hipertensiva"],["Alrededor del 85 % de las hemorragias subaracnoideas no traumáticas se deben a la rotura de un aneurisma sacular de las arterias del polígono de Willis.","Falso: las MAV son una causa posible pero mucho más rara que el aneurisma, que sigue siendo con mucho la primera etiología.","Falso: la angiopatía amiloide provoca sobre todo hemorragias lobares intraparenquimatosas del sujeto mayor, no la hemorragia meníngea.","Falso: la rotura de las perforantes por HTA produce la hemorragia intraparenquimatosa profunda, no la hemorragia subaracnoidea."]],
  "106": ["¿Cuál es la causa más frecuente de hemorragia cerebral intraparenquimatosa no traumática?",["La hipertensión arterial","La angiopatía amiloide cerebral","La rotura de un aneurisma del polígono de Willis","Una malformación arteriovenosa"],["La HTA es la primera causa de hemorragia intraparenquimatosa, por rotura de las arterias perforantes profundas (núcleos grises, cápsula, protuberancia).","Falso: la angiopatía amiloide es una causa frecuente pero sobre todo de hemorragias lobares del sujeto mayor; la HTA domina globalmente.","Falso: la rotura de aneurisma produce típicamente una hemorragia subaracnoidea, no intraparenquimatosa.","Falso: las MAV son una causa posible pero rara, muy por detrás de la HTA, primera etiología."]],
  "107": ["¿Qué distingue anatómicamente un hematoma extradural (epidural) de un hematoma subdural?",["El epidural está entre el hueso y la duramadre, y el subdural entre la duramadre y la aracnoides","El epidural está entre la duramadre y la aracnoides, y el subdural entre el hueso y la duramadre","El epidural está en el parénquima, y el subdural por debajo de la aracnoides","El epidural está entre la aracnoides y la piamadre, y el subdural en el parénquima"],["El hematoma epidural se sitúa entre la tabla ósea y la duramadre; el subdural se sitúa entre la duramadre y la aracnoides.","Falso: es lo inverso, el epidural está contra el hueso y el subdural por debajo de la duramadre.","Falso: el sangrado parenquimatoso es intraaxial y el subaracnoideo está por debajo de la aracnoides; ninguno de los dos es esos hematomas.","Falso: el espacio entre aracnoides y piamadre es el espacio subaracnoideo, y el parénquima corresponde a la hemorragia intracerebral."]],
  "108": ["¿Cómo se caracteriza la afasia de Broca (motora)?",["Un lenguaje no fluido y laborioso con comprensión preservada","Un lenguaje fluido pero incomprensible con comprensión abolida","Una afectación predominante de la repetición con expresión conservada","Una pérdida aislada de la denominación de los objetos"],["La afasia de Broca (lesión frontal) produce un lenguaje reducido y no fluido, mientras que la comprensión se conserva globalmente.","Falso: ese cuadro (habla fluida, comprensión hundida) define la afasia de Wernicke.","Falso: la afectación electiva de la repetición caracteriza la afasia de conducción (fascículo arqueado).","Falso: la falta aislada de la palabra define la afasia anómica, no la de Broca."]],
  "109": ["¿Qué cuadro evoca una afasia de Wernicke?",["Un lenguaje fluido pero erróneo con comprensión muy alterada","Un lenguaje reducido y laborioso con comprensión conservada","Una afectación electiva de la repetición, con expresión conservada","Una pérdida aislada de la denominación, con lenguaje fluido"],["La afasia de Wernicke (lesión temporal posterior) asocia un habla fluida llena de parafasias a una comprensión hundida, sin conciencia del trastorno.","Falso: ese perfil no fluido con comprensión preservada corresponde a la afasia de Broca.","Falso: la afectación predominante de la repetición define la afasia de conducción.","Falso: la falta aislada de la palabra sin trastorno de comprensión define la afasia anómica."]],
  "110": ["La afasia de conducción, ligada a una lesión del fascículo arqueado, se caracteriza sobre todo por:",["Una afectación predominante de la repetición, con el paciente consciente del trastorno","Una afectación completa de la comprensión y de la expresión","Una repetición conservada con comprensión hundida","Una pérdida aislada de la denominación de los objetos"],["La afasia de conducción (fascículo arqueado) altera sobre todo la repetición, y la expresión y la comprensión quedan relativamente preservadas.","Falso: la abolición simultánea de la comprensión y de la expresión define la afasia global.","Falso: la repetición preservada orienta hacia las afasias transcorticales, al contrario de la de conducción.","Falso: la falta aislada de la palabra define la afasia anómica, no la afasia de conducción."]],
  "111": ["¿Qué distingue una afasia de una disartria?",["La afasia es un trastorno central del lenguaje y la disartria un trastorno de la articulación","La afasia es un trastorno de la articulación y la disartria un trastorno central del lenguaje","La afasia es un trastorno de la fonación y la disartria un trastorno del lenguaje","La afasia es un trastorno de la comprensión y la disartria un trastorno de la fonación"],["Exacto: la afasia afecta a la elaboración central del lenguaje, mientras que la disartria es un trastorno motor de la ejecución articulatoria.","Falso: es la inversión exacta de ambas definiciones (afasia = lenguaje central, disartria = articulación).","Falso: el trastorno de la fonación es la disfonía, y la disartria afecta a la articulación, no al lenguaje central.","Falso: la afasia no se reduce a la comprensión, y el trastorno de la fonación es la disfonía, no la disartria."]],
  "112": ["¿Cómo se define la apraxia ideomotora?",["El paciente concibe el acto solicitado pero no consigue ejecutarlo correctamente","El paciente ha perdido la concepción de la secuencia de los gestos de una acción compleja","El paciente ya no sabe utilizar un objeto familiar que, sin embargo, manipula","El paciente no consigue dibujar ni ensamblar una figura geométrica"],["Exacto: en la apraxia ideomotora, la idea del acto se conserva pero su ejecución gestual fracasa.","Falso: la pérdida del plan secuencial de una acción compleja define la apraxia ideatoria, no la ideomotora.","Falso: el uso erróneo de un objeto que sin embargo se manipula corresponde sobre todo a la apraxia ideatoria o a la agnosia de uso.","Falso: el fracaso de la copia o del ensamblaje caracteriza la apraxia constructiva, no la ideomotora."]],
  "113": ["La apraxia constructiva (incapacidad de dibujar o de ensamblar objetos) se relaciona sobre todo con:",["Una afectación visuoespacial, de predominio en el hemisferio derecho","Una afectación del lenguaje, de predominio en el hemisferio izquierdo","Una afectación motora, de predominio en la corteza frontal precentral","Una afectación de la coordinación, de predominio cerebeloso"],["Exacto: la apraxia constructiva tiene un fuerte componente visuoespacial y predomina en las lesiones parietooccipitales derechas.","Falso: la afectación del lenguaje (hemisferio izquierdo dominante) produce una afasia, no una apraxia constructiva.","Falso: la corteza precentral gobierna la orden motora; su lesión produce un déficit motor, no un trastorno constructivo.","Falso: el cerebelo regula la coordinación del movimiento, no la organización visuoespacial del dibujo."]],
  "114": ["La negligencia espacial (heminegligencia) aparece la mayoría de las veces tras una lesión:",["Del hemisferio derecho (no dominante), con negligencia del lado izquierdo","Del hemisferio izquierdo (dominante), con negligencia del lado derecho","Del lóbulo occipital derecho, con hemianopsia lateral izquierda","Del tronco cerebral, con desviación lateral de la mirada"],["Exacto: el hemisferio derecho gobierna la atención de todo el espacio, por lo que su lesión provoca una negligencia izquierda grave.","Falso: la negligencia derecha (lesión izquierda) existe pero es rara y discreta; la forma típica grave es izquierda.","Falso: una lesión occipital produce una hemianopsia (déficit perceptivo), distinta de la negligencia (déficit atencional).","Falso: la negligencia es un trastorno cortical parietal derecho, no una afectación oculomotora del tronco cerebral."]],
  "115": ["¿Cómo se define la anosognosia?",["El paciente no toma conciencia de su propio déficit neurológico","El paciente no reconoce como suyo el lado opuesto de su cuerpo","El paciente no reconoce las caras familiares que ve","El paciente no reconoce los objetos palpados con los ojos cerrados"],["Exacto: la anosognosia es el desconocimiento por parte del paciente de su déficit, por ejemplo negar su hemiplejía.","Falso: el no reconocimiento de un hemicuerpo como propio define la asomatognosia.","Falso: la incapacidad de reconocer las caras es la prosopagnosia, una agnosia visual.","Falso: la incapacidad de identificar un objeto por el tacto es la astereognosia."]],
  "116": ["¿Qué es una agnosia?",["La incapacidad de identificar un estímulo a pesar de tener los órganos sensoriales intactos","La incapacidad de ejecutar un gesto aprendido a pesar de una motricidad intacta","La incapacidad de producir el lenguaje a pesar de una articulación intacta","La incapacidad de percibir un estímulo por lesión del órgano sensorial"],["Exacto: la agnosia es un trastorno del reconocimiento por afectación de las áreas asociativas, mientras las vías sensoriales primarias permanecen intactas.","Falso: el fracaso de un gesto aprendido sin déficit motor define la apraxia, no la agnosia.","Falso: el trastorno de la producción del lenguaje es la afasia, no la agnosia.","Falso: la agnosia supone precisamente un órgano sensorial funcional; una lesión del órgano produce un déficit sensorial (ceguera, sordera)."]],
  "117": ["¿Cómo se denomina la incapacidad específica de reconocer las caras?",["La prosopagnosia","La astereognosia","La agnosia auditiva","La anomia"],["La prosopagnosia es una agnosia visual específica de las caras.","La astereognosia es la incapacidad de reconocer los objetos por el tacto.","La agnosia auditiva se refiere al no reconocimiento de los sonidos.","La anomia es un trastorno de la denominación (lenguaje), no del reconocimiento de las caras."]],
  "118": ["¿Cuál es la diferencia entre amnesia anterógrada y amnesia retrógrada?",["La anterógrada impide adquirir nuevos recuerdos, y la retrógrada borra los recuerdos anteriores al desencadenante","La anterógrada borra los recuerdos antiguos, y la retrógrada impide adquirir nuevos recuerdos","La anterógrada y la retrógrada afectan ambas a los recuerdos anteriores al desencadenante","La anterógrada respeta la memoria de trabajo, y la retrógrada respeta la memoria a largo plazo"],["Amnesia anterógrada = imposibilidad de formar nuevos recuerdos; retrógrada = pérdida de los recuerdos anteriores al acontecimiento desencadenante.","Falso: es lo inverso, la anterógrada bloquea la adquisición y la retrógrada borra el pasado.","Falso: solo la retrógrada borra el pasado; la anterógrada afecta a la adquisición de nuevos recuerdos.","Falso: la distinción se refiere a la cronología (antes/después del desencadenante), no al tipo de memoria."]],
  "119": ["¿Qué conjunto de signos evoca un síndrome frontal?",["Desinhibición o apatía, reflejos arcaicos y trastornos atencionales","Hemianopsia lateral homónima, agnosia visual y alexia","Síndrome de Korsakoff, amnesia anterógrada y fabulaciones","Ataxia cerebelosa, dismetría y temblor de acción"],["El síndrome frontal asocia trastornos del comportamiento (desinhibición o abulia), reaparición de reflejos arcaicos (prensión, succión) y déficit atencional.","Falso: ese cuadro evoca una afectación occipital, no un síndrome frontal.","Falso: ese cuadro evoca una afectación temporal interna (hipocampo), no un síndrome frontal.","Falso: ese cuadro evoca una afectación cerebelosa, no un síndrome frontal."]],
  "120": ["El síndrome de Klüver-Bucy, ligado a una afectación temporal bilateral, asocia:",["Una placidez, una hiperoralidad y una hipersexualidad","Una apatía, una hemianopsia y una heminegligencia","Una desinhibición, una prensión forzada y una abulia","Una amnesia anterógrada, una anosognosia y una fabulación"],["El Klüver-Bucy (lesión temporal bilateral) asocia placidez, hiperoralidad (objetos llevados a la boca), hipersexualidad y disminución del reconocimiento de los allegados.","Falso: ese cuadro evoca una afectación parietooccipital, no el Klüver-Bucy.","Falso: ese cuadro evoca un síndrome frontal, no el Klüver-Bucy.","Falso: ese cuadro evoca un síndrome de Korsakoff, no el Klüver-Bucy."]],
  "121": ["¿De qué depende el mantenimiento de la conciencia?",["De la vigilancia que asegura el SRAA del tronco cerebral y del contenido que aseguran los hemisferios","De la vigilancia que aseguran los hemisferios y del contenido que asegura el SRAA del tronco cerebral","De la vigilancia que asegura el SRAA y del contenido que asegura el tálamo de relevo solo","De la vigilancia que aseguran los núcleos grises centrales y del contenido que asegura la corteza frontal sola"],["La conciencia se basa en la vigilancia (sistema reticular activador ascendente, tronco cerebral) y en el contenido (integridad de los dos hemisferios).","Falso: es lo inverso, la vigilancia depende del SRAA del tronco y el contenido de la integridad de los hemisferios.","Falso: el tálamo participa en la vigilia, pero el contenido de la conciencia depende de los dos hemisferios, no del tálamo solo.","Falso: la vigilancia depende del SRAA del tronco, no de los núcleos grises; el contenido implica el conjunto de los hemisferios y no solo la corteza frontal."]],
  "122": ["¿Qué distingue la postura de decorticación de la postura de descerebración en un paciente comatoso?",["La decorticación asocia una flexión de los miembros superiores, y la descerebración una extensión de los miembros superiores","La decorticación asocia una extensión de los miembros superiores, y la descerebración una flexión de los miembros superiores","La decorticación indica una lesión del tronco cerebral, y la descerebración una lesión cortical","La decorticación es de peor pronóstico que la descerebración"],["Decorticación = flexión de los brazos (lesión corticoespinal por encima del tronco); descerebración = extensión de los brazos (lesión del tronco cerebral superior), de peor pronóstico.","Falso: es lo inverso, la decorticación es en flexión y la descerebración en extensión.","Falso: la decorticación traduce una afectación corticoespinal por encima del tronco y la descerebración una afectación del tronco superior.","Falso: es la descerebración la que traduce una afectación más profunda y de peor pronóstico."]],
  "123": ["Respecto a las crisis epilépticas, ¿qué proposición es correcta?",["Las crisis generalizadas alteran la conciencia desde el principio, y las crisis focales dependen de la zona cortical implicada","Las crisis focales alteran la conciencia desde el principio, y las crisis generalizadas permanecen localizadas en un foco","Las ausencias son crisis focales, y las crisis tonicoclónicas son crisis focales secundariamente bilaterales","Las crisis generalizadas respetan la conciencia, y las crisis focales la abolen siempre"],["Verdadero: las crisis generalizadas (tonicoclónicas, ausencias) implican los dos hemisferios con alteración de la conciencia desde el principio; las crisis focales nacen de un foco cortical localizado y su semiología refleja la zona afectada.","Falso: es lo inverso. La crisis focal parte de un foco localizado (la conciencia puede conservarse) y la crisis generalizada afecta a los dos hemisferios desde el principio, con pérdida de conciencia.","Falso: la ausencia («pequeño mal») es una crisis GENERALIZADA desde el principio, no focal; la crisis tonicoclónica puede ser generalizada desde el principio o seguir a una crisis focal.","Falso: la generalizada altera la conciencia desde el principio; la focal puede al contrario conservarla (crisis focal simple) o alterarla (crisis focal compleja)."]],
  "124": ["¿Cómo se define una demencia?",["Un deterioro global y progresivo de funciones cognitivas previamente adquiridas, con repercusión en la autonomía","Un trastorno cognitivo agudo y fluctuante, reversible y sin declive duradero de las funciones adquiridas","Un déficit cognitivo global presente desde el nacimiento y estable a lo largo de la vida","Una queja mnésica subjetiva aislada sin déficit objetivo ni repercusión funcional"],["Verdadero: la demencia es un declive cognitivo ADQUIRIDO, global y la mayoría de las veces progresivo, suficiente para repercutir en la vida diaria y en la autonomía.","Falso: ese cuadro agudo, fluctuante y reversible define el síndrome confusional (delirium), no la demencia, que es duradera y progresiva.","Falso: un déficit cognitivo congénito y estable corresponde a la discapacidad intelectual; la demencia es una PÉRDIDA de funciones previamente adquiridas.","Falso: una simple queja mnésica sin déficit objetivo ni repercusión corresponde al envejecimiento normal o a un trastorno leve, no a una demencia."]],
  "125": ["Según los criterios diagnósticos, una demencia asocia un trastorno de la memoria con al menos otro déficit. ¿Cuál de estos?",["Una afasia, una apraxia, una agnosia o una alteración de las funciones ejecutivas","Una fluctuación de la vigilancia con inatención de instauración aguda","Una hemiparesia o una afectación sensitiva de un hemicuerpo","Un ánimo triste con pérdida de impulso y de interés"],["Verdadero: la demencia exige un trastorno mnésico ASOCIADO a al menos otro déficit cognitivo entre afasia, apraxia, agnosia o afectación de las funciones ejecutivas.","Falso: la fluctuación de la vigilancia y la inatención aguda caracterizan el delirium; no son los déficits cognitivos requeridos para la demencia.","Falso: son signos neurológicos focales motores/sensitivos, y no los déficits cognitivos (afasia, apraxia, agnosia, disejecutivo) que definen la demencia.","Falso: la tristeza y la pérdida de interés evocan un síndrome depresivo (posible pseudodemencia), pero no cuentan como déficit cognitivo diagnóstico de demencia."]],
  "126": ["¿Cuál es la forma más frecuente de demencia degenerativa (primaria)?",["La enfermedad de Alzheimer","La demencia por cuerpos de Lewy","La demencia frontotemporal","La demencia vascular"],["La enfermedad de Alzheimer es la demencia primaria más frecuente (acumulación de β-amiloide y de proteína tau).","La demencia por cuerpos de Lewy es la 2.ª más frecuente, después del Alzheimer.","La demencia frontotemporal es más rara y más precoz.","La demencia vascular es una demencia secundaria, menos frecuente que la enfermedad de Alzheimer."]],
  "127": ["¿Qué anomalía proteica está en el centro de la fisiopatología de la enfermedad de Alzheimer?",["La acumulación cerebral de péptido β-amiloide y de proteína tau","La acumulación cerebral de α-sinucleína en cuerpos de Lewy","La inclusión neuronal de proteína TDP-43 y de tau en los lóbulos frontotemporales","La acumulación de una proteína prión mal conformada (PrPsc)"],["El Alzheimer se caracteriza por los depósitos de β-amiloide (placas) y la acumulación de proteína tau (degeneración neurofibrilar).","Falso: la acumulación de α-sinucleína (cuerpos de Lewy) caracteriza la demencia por cuerpos de Lewy y la enfermedad de Parkinson, no el Alzheimer.","Falso: las inclusiones de TDP-43 y la atrofia frontotemporal definen la degeneración frontotemporal, y no la enfermedad de Alzheimer.","Falso: la acumulación de prion patológico caracteriza las encefalopatías espongiformes (Creutzfeldt-Jakob), no la enfermedad de Alzheimer."]],
  "128": ["Un hombre de 72 años presenta, desde hace 2 años, olvidos de acontecimientos recientes que se agravan progresivamente, una desorientación temporal y un MMSE de 21/30. ¿Qué diagnóstico plantea en primer lugar?",["Una enfermedad de Alzheimer","Un síndrome confusional agudo (delirium)","Una demencia vascular","Una pseudodemencia depresiva"],["Verdadero: inicio insidioso, declive mnésico progresivo a lo largo de varios años, desorientación temporal y MMSE bajo en un sujeto mayor orientan en primer lugar hacia una enfermedad de Alzheimer.","Falso: el delirium se instaura en horas o días, fluctúa y es reversible, al contrario de este empeoramiento lento y continuo durante 2 años.","Falso: la demencia vascular evoluciona más bien «en escalones» con signos focales y factores de riesgo vascular, mientras que aquí el empeoramiento es lento y continuo, más típico del Alzheimer.","Falso: la depresión del sujeto mayor puede imitar una demencia, pero se acompaña de un ánimo triste y de quejas en primer plano, sin ese declive mnésico progresivo durante 2 años."]],
  "129": ["La demencia por cuerpos de Lewy asocia típicamente:",["Declive cognitivo fluctuante, parkinsonismo y alucinaciones visuales","Declive cognitivo progresivo, amnesia anterógrada y desorientación temporoespacial","Declive cognitivo de empeoramiento por escalones y signos neurológicos focales","Trastornos conductuales precoces, desinhibición y apatía en primer plano"],["Tríada de la demencia por cuerpos de Lewy (depósitos de α-sinucleína): fluctuaciones cognitivas, síndrome parkinsoniano y alucinaciones visuales precoces.","Falso: ese es el perfil de la enfermedad de Alzheimer, donde las alucinaciones visuales y el parkinsonismo precoces están ausentes.","Falso: la evolución en escalones con déficits focales es la demencia vascular, no la demencia por cuerpos de Lewy.","Falso: la desinhibición y la apatía inaugurales caracterizan la demencia frontotemporal, no la demencia por cuerpos de Lewy."]],
  "130": ["¿Qué caracteriza el cuadro inicial de una demencia frontotemporal (variante conductual)?",["Trastornos precoces del comportamiento y de la personalidad más que mnésicos","Un trastorno mnésico anterógrado aislado y una desorientación en primer plano","Alucinaciones visuales y fluctuaciones cognitivas en primer plano","Una caída brusca por escalones de las funciones con signos focales"],["La demencia frontotemporal (variante conductual) comienza por la desinhibición, la apatía y la pérdida de empatía, y la memoria se conserva durante mucho tiempo.","Falso: la amnesia anterógrada inaugural es la enfermedad de Alzheimer; la frontotemporal comienza por el comportamiento.","Falso: las alucinaciones visuales y las fluctuaciones precoces orientan hacia la demencia por cuerpos de Lewy, no hacia la frontotemporal.","Falso: el empeoramiento en escalones con déficits focales es la demencia vascular, no la frontotemporal."]],
  "131": ["¿A qué se llama una demencia «mixta»?",["A la coexistencia de lesiones de enfermedad de Alzheimer y de lesiones vasculares","A la coexistencia de lesiones de enfermedad de Alzheimer y de cuerpos de Lewy","A la aparición de una demencia frontotemporal y de una afectación de la motoneurona","A la asociación de un declive cognitivo y de un síndrome depresivo mayor"],["La demencia mixta asocia las lesiones degenerativas de la enfermedad de Alzheimer y lesiones isquémicas vasculares en un mismo paciente.","Falso: esa asociación existe, pero el término «demencia mixta» designa por convención la asociación Alzheimer + lesiones vasculares.","Falso: ese es el continuo demencia frontotemporal-ELA, y no lo que abarca la demencia mixta.","Falso: la depresión puede producir una pseudodemencia, pero no es la definición de la demencia mixta."]],
  "132": ["¿Qué distingue el síndrome confusional agudo (delirium) de una demencia?",["El delirium es de instauración aguda, fluctuante y a menudo reversible, y la demencia es crónica y progresiva","El delirium se instaura a lo largo de varios años mientras que la demencia aparece en unas horas","El delirium altera la memoria respetando la vigilancia, y la demencia altera la vigilancia","El delirium es siempre irreversible mientras que la demencia regresa espontáneamente"],["El delirium se instaura en horas o días, fluctúa (empeoramiento vespertino) y es reversible; la demencia es un declive crónico y progresivo.","Falso: las duraciones están invertidas, pues el delirium es agudo (horas/días) y la demencia crónica (meses/años).","Falso: es lo inverso, el delirium perturba la vigilancia/atención mientras que la vigilancia se conserva mucho tiempo en la demencia.","Falso: el delirium es a menudo reversible y la demencia no regresa espontáneamente; las dos afirmaciones están invertidas."]],
  "133": ["Respecto al síndrome confusional agudo (delirium), ¿qué proposición es correcta?",["Es más frecuente en la persona mayor, fluctúa durante el día y depende a menudo de un factor desencadenante","Aparece sobre todo en el adulto joven sano y se estabiliza una vez instaurado","Se basa siempre en una lesión cerebral estructural objetivada en la TC","Evoluciona lentamente a lo largo de varios meses sin que se encuentre un factor desencadenante"],["El delirium, frecuente en el sujeto mayor frágil, fluctúa (síndrome vespertino) y traduce un factor precipitante orgánico o tóxico (infección, medicamento, hospitalización).","Falso: afecta sobre todo al sujeto mayor frágil y fluctúa durante el día en lugar de estabilizarse.","Falso: el delirium es la mayoría de las veces funcional (metabólico/tóxico), sin lesión estructural obligatoria.","Falso: una instauración lenta a lo largo de meses sin causa precipitante es la demencia, no el delirium."]],
  "134": ["El Mini-Mental State Examination (MMSE) es un test cognitivo de cribado. ¿Qué orden de magnitud sugiere un deterioro cognitivo?",["Una puntuación inferior a 24/30","Una puntuación inferior a 20/30","Una puntuación inferior a 18/30","Una puntuación inferior a 10/30"],["Un MMSE < 24/30 es el umbral habitual de alerta que orienta hacia un deterioro cognitivo, a interpretar según la edad y el nivel sociocultural.","Falso: bajar el umbral de cribado a 20/30 dejaría pasar las afectaciones incipientes, que ya se señalan desde < 24/30.","Falso: < 18/30 corresponde ya a un deterioro moderado o grave, no al umbral de cribado de una afectación incipiente (24/30).","Falso: < 10/30 traduce una demencia grave y no el umbral a partir del cual se plantea un deterioro cognitivo."]],
  "135": ["¿Qué modalidad corresponde a la sensibilidad PROFUNDA?",["La sensibilidad vibratoria (palestesia)","La sensibilidad térmica (calor/frío)","La sensibilidad dolorosa (nocicepción)","El tacto grosero (protopático)"],["La palestesia (vibración) corresponde a la sensibilidad profunda, que discurre por los cordones posteriores; la térmica, el dolor y el tacto grosero son superficiales (vía espinotalámica).","Falso: la termosensibilidad es superficial (vía espinotalámica lateral), no profunda.","Falso: el dolor es superficial (vía espinotalámica lateral), no profundo.","Falso: el tacto grosero protopático es superficial (vía espinotalámica anterior), no profundo."]],
  "136": ["¿Cómo se distingue la sensibilidad protopática de la sensibilidad epicrítica?",["Protopática = tacto grosero no discriminativo; epicrítica = tacto fino discriminativo","Protopática = tacto fino discriminativo; epicrítica = tacto grosero no discriminativo","Protopática = sensibilidad térmica; epicrítica = sensibilidad dolorosa","Protopática = propiocepción; epicrítica = sensibilidad vibratoria"],["El tacto protopático (grosero, vía espinotalámica anterior) se opone al tacto epicrítico (fino y discriminativo, cordones posteriores).","Falso: es lo inverso, protopático = grosero y epicrítico = fino.","Falso: ambos términos califican el tacto, no la sensibilidad térmica ni la álgica.","Falso: la propiocepción (batiestesia) y la vibración (palestesia) son sensibilidades profundas, no el tacto."]],
  "137": ["¿Con qué instrumento y sobre qué estructuras se explora la sensibilidad vibratoria (palestesia)?",["Un diapasón (128 Hz) aplicado sobre los relieves óseos","Una aguja puntiaguda sobre la pulpa de los dedos","Dos tubos de agua caliente y fría","Un algodón que roza la piel"],["La palestesia se explora con un diapasón de 128 Hz colocado sobre las prominencias óseas (maléolos, rótula, esternón...); depende de los cordones posteriores.","La aguja/el pinchazo explora la sensibilidad dolorosa (espinotalámica lateral).","Los tubos de calor/frío exploran la sensibilidad térmica.","El algodón explora el tacto grosero (espinotalámica anterior), no la vibración."]],
  "138": ["La sensibilidad al dolor y a la temperatura discurre por qué vía, y cómo se explora?",["Vía espinotalámica lateral; explorada con el pinchazo y el calor/frío","Vía de los cordones posteriores; explorada con el diapasón","Vía espinotalámica anterior; explorada con el tacto con algodón","Haz piramidal; explorado con el balance de fuerza"],["La vía espinotalámica lateral vehicula el dolor y la temperatura; se prueba con el pinchazo (dolor) y los tubos de calor/frío (temperatura).","Falso: los cordones posteriores vehiculan la vibración y la propiocepción, exploradas con el diapasón, no el dolor ni la temperatura.","Falso: la vía espinotalámica anterior vehicula el tacto grosero (algodón), no el dolor ni la temperatura.","Falso: el haz piramidal es motor y se prueba con la fuerza, no tiene papel sensitivo."]],
  "139": ["¿A qué se llama estereognosia?",["A la capacidad de reconocer un objeto por el tacto (sin verlo)","A la percepción de las vibraciones","A la percepción de la posición articular","Al reconocimiento de cifras dibujadas sobre la piel"],["La estereognosia es el reconocimiento de los objetos por el tacto (gnosia táctil); combina sensibilidades superficial y profunda y una integración cortical.","La percepción de las vibraciones es la palestesia.","La percepción de la posición es la batiestesia (propiocepción).","Eso define la grafestesia, no la estereognosia."]],
  "140": ["¿Cómo se caracteriza una polineuropatía (p. ej. diabética, la más frecuente)?",["Afectación simétrica y distal, en «guantes y calcetines»","Afectación asimétrica de varios nervios no contiguos","Afectación focal de un solo tronco nervioso","Afectación del territorio de una sola raíz nerviosa"],["La polineuropatía es difusa, simétrica y de predominio distal (déficit en guantes/calcetines); la diabetes es su causa más frecuente.","Falso: eso describe la mononeuritis múltiple (multineuritis), no la polineuropatía.","Falso: la afectación de un solo tronco define una mononeuropatía.","Falso: la afectación de una raíz define una radiculopatía."]],
  "141": ["¿Cuál es la mononeuropatía compresiva más frecuente?",["El síndrome del túnel carpiano (nervio mediano en la muñeca)","El síndrome del túnel cubital (nervio cubital en el codo)","El síndrome del túnel tarsiano (nervio tibial en el tobillo)","La parálisis del nervio peroneo en el cuello del peroné"],["La compresión del nervio mediano en el túnel carpiano es la mononeuropatía compresiva más frecuente, por delante de la afectación cubital en el codo.","Falso: la compresión cubital en el codo (canal epitrocleoolecraniano) es la 2.ª más frecuente, no la primera.","Falso: la compresión del nervio tibial en el túnel tarsiano es rara en comparación con el túnel carpiano.","Falso: la compresión del nervio peroneo común en el cuello del peroné es menos frecuente que el túnel carpiano."]],
  "142": ["¿En qué consiste el signo de Tinel?",["Una descarga eléctrica provocada por la percusión sobre el trayecto de un nervio","Parestesias reproducidas por la flexión forzada mantenida de la muñeca","Una descarga en el raquis y en los miembros a la flexión del cuello","Un dolor reproducido por la presión directa sostenida sobre el tronco nervioso"],["El signo de Tinel es una sensación de hormigueo o de descarga desencadenada por la percusión del nervio comprimido (p. ej. el mediano en la muñeca).","Falso: esa maniobra describe el signo de Phalen, no el signo de Tinel.","Falso: esa descarga a la flexión cervical es el signo de Lhermitte, no el signo de Tinel.","Falso: el dolor a la presión sostenida corresponde a un test de compresión, distinto de la percusión breve del Tinel."]],
  "143": ["En la electroneuromiografía, ¿qué orienta hacia una afectación DESMIELINIZANTE más que axonal?",["Una ralentización de las velocidades de conducción con alargamiento de las latencias","Una disminución de la amplitud de los potenciales con velocidad conservada","Una actividad de denervación marcada en reposo con la aguja","Una reducción del reclutamiento con trazado pobre al esfuerzo"],["La afectación desmielinizante ralentiza la conducción: velocidades disminuidas, latencias alargadas y bloqueos de conducción, al contrario de la afectación axonal.","Falso: la caída de amplitud con velocidad preservada caracteriza la afectación AXONAL, no desmielinizante.","Falso: las fibrilaciones y los potenciales de denervación traducen sobre todo una pérdida AXONAL.","Falso: la rarefacción del reclutamiento refleja la pérdida de unidades motoras (axonal), no la desmielinización."]],
  "144": ["Una afectación del sistema nervioso periférico (frente a una afectación central) se traduce típicamente en:",["Una debilidad flácida con hipotonía e hipo- o arreflexia","Una debilidad espástica con hiperreflexia y signo de Babinski","Una debilidad con clonus y abolición de los reflejos cutáneos abdominales","Una debilidad sin amiotrofia, con reflejos vivos y difundidos"],["La afectación periférica (motoneurona inferior) produce debilidad flácida, hipotonía, hipo/arreflexia y amiotrofia precoz.","Falso: la espasticidad, la hiperreflexia y el Babinski indican una afectación CENTRAL (motoneurona superior).","Falso: el clonus y la pérdida de los reflejos cutáneos abdominales orientan hacia una afectación piramidal CENTRAL.","Falso: unos reflejos vivos y difundidos sin amiotrofia evocan una afectación CENTRAL, no periférica."]],
  "145": ["Respecto a la vascularización de la médula espinal, ¿qué proposición es correcta?",["La arteria espinal anterior irriga los dos tercios anteriores de la médula","Las arterias espinales posteriores irrigan los dos tercios anteriores","La arteria espinal anterior solo irriga los cordones posteriores","La arteria de Adamkiewicz vasculariza únicamente la médula cervical"],["La arteria espinal anterior vasculariza los 2/3 anteriores (de ahí el síndrome medular anterior en caso de oclusión); las arterias espinales posteriores irrigan el 1/3 posterior.","Falso: las arterias espinales posteriores solo irrigan el 1/3 posterior (cordones posteriores).","Falso: los cordones posteriores dependen de las arterias espinales POSTERIORES, no de la anterior.","Falso: la arteria de Adamkiewicz refuerza sobre todo la médula toracolumbar, no la médula cervical."]],
  "146": ["¿Según qué principios se desarrolla el desarrollo motor del niño?",["En sentido cefalocaudal y proximodistal, de lo simple a lo complejo","En sentido caudocefálico y distoproximal, de lo complejo a lo simple","En sentido cefalocaudal pero distoproximal, de las extremidades hacia el tronco","En sentido proximodistal pero caudocefálico, de los pies hacia la cabeza"],["El desarrollo motor sigue un orden cefalocaudal (de la cabeza a los pies) y proximodistal (del tronco a las extremidades), de lo simple a lo complejo.","Falso: esos sentidos son el inverso exacto de los principios cefalocaudal y proximodistal reales.","Falso: el control va del tronco hacia las extremidades (proximodistal), no al contrario.","Falso: el control se adquiere de la cabeza hacia los pies (cefalocaudal), no de los pies hacia la cabeza."]],
  "147": ["¿Qué adquisición motora se espera hacia los 0 a 3 meses en el lactante nacido a término?",["El control cefálico en decúbito prono","La sedestación sin apoyo","La prensión voluntaria de los objetos","El volteo espalda-vientre activo"],["Verdadero: entre los 0 y los 3 meses, el lactante endereza y sostiene la cabeza en decúbito prono; los reflejos primitivos están todavía presentes.","Falso: la sedestación independiente se adquiere hacia los 6-9 meses, no a los 0-3 meses.","Falso: la prensión voluntaria (presa dirigida) aparece hacia los 4-5 meses, no a los 0-3 meses.","Falso: el volteo completo se adquiere hacia los 5-6 meses, no a los 0-3 meses."]],
  "148": ["¿En qué periodo alcanza la sinaptogénesis su pico, lo que hace de esa ventana un momento clave de intervención?",["Durante los tres primeros años de vida","Durante el periodo fetal únicamente","Durante la segunda infancia (6-10 años)","Durante la adolescencia y la adultez joven"],["Verdadero: la sinaptogénesis se intensifica sobre todo después del nacimiento, con un pico entre los 0 y los 3 años, periodo de plasticidad máxima.","Falso: la sinaptogénesis continúa y culmina sobre todo después del nacimiento, no solo in utero.","Falso: en ese periodo domina más bien la poda sináptica; el pico de formación es anterior (0-3 años).","Falso: la adolescencia está marcada por la maduración prefrontal y la poda, no por el pico sináptico (0-3 años)."]],
  "149": ["¿En qué principio se basa la poda sináptica (pruning)?",["Las sinapsis utilizadas se refuerzan y las no utilizadas se eliminan","Las sinapsis más utilizadas se eliminan con prioridad","Las sinapsis se eliminan al azar, sin relación con el uso","El número de sinapsis aumenta de forma regular con la edad"],["Verdadero: la poda elimina las conexiones poco solicitadas y consolida las activadas por la experiencia, afinando los circuitos.","Falso: es lo inverso; son las sinapsis utilizadas las que se refuerzan y se conservan.","Falso: la poda está guiada por la actividad (dependiente de la experiencia), no es aleatoria.","Falso: después del pico precoz, la poda reduce el número de sinapsis durante la infancia y la adolescencia."]],
  "150": ["¿Qué elemento constituye un signo de alerta del desarrollo neurológico?",["La ausencia de marcha autónoma a los 18 meses","El control cefálico adquirido hacia los 3 meses","La aparición de la sonrisa social hacia los 2 meses","La sedestación sin apoyo hacia los 8 meses"],["Verdadero: la ausencia de marcha a los 18 meses es un signo de alerta (retraso motor, incluso parálisis cerebral) que obliga a una valoración.","Falso: es una adquisición motora normal y esperada a esa edad, no un signo de alerta.","Falso: la sonrisa social hacia los 2 meses es una etapa normal, no un signo de alerta.","Falso: la sedestación independiente hacia los 8 meses se sitúa dentro del margen normal, no es un signo de alerta."]],
  "151": ["¿Por qué la pérdida de competencias ya adquiridas en un niño es particularmente preocupante?",["Porque una regresión puede revelar una patología neurodegenerativa","Porque un simple retraso global recupera espontáneamente los logros perdidos","Porque una desviación del desarrollo provoca una regresión motora aislada","Porque un estancamiento prolongado de las adquisiciones precede a toda regresión normal"],["Verdadero: la pérdida de competencias previamente adquiridas es un signo de alerta mayor (enfermedad neurodegenerativa, metabólica o epilepsia evolutiva) que obliga a un estudio urgente.","Falso: un retraso global ralentiza la adquisición pero no hace perder competencias ya instaladas; la pérdida de logros es cualitativamente distinta y siempre patológica.","Falso: la desviación traduce un desarrollo atípico sin pérdida de logros, y no se limita al dominio motor; no es el mecanismo de la regresión.","Falso: un estancamiento es en sí mismo un signo de alerta y la regresión no tiene nada de normal; ninguna pérdida de competencias corresponde a un proceso fisiológico."]],
  "152": ["¿Cuál es la diferencia entre un «retraso» y una «desviación» del desarrollo?",["El retraso sigue la secuencia normal pero más lentamente, y la desviación es atípica","El retraso corresponde a esquemas atípicos y la desviación a una ralentización","El retraso es definitivo y la desviación siempre transitoria","El retraso afecta a lo motor y la desviación solo al lenguaje"],["Verdadero: en el retraso las etapas esperadas se alcanzan fuera de plazo; en la desviación el desarrollo es cualitativamente anormal (esquemas atípicos).","Falso: es la inversión exacta de las dos definiciones.","Falso: ni la cronicidad ni la reversibilidad distinguen ambos; la diferencia está en la secuencia (lenta frente a atípica).","Falso: tanto el retraso como la desviación pueden afectar a todos los dominios (motor, cognitivo, lingüístico, social)."]],
  "153": ["Entre estas situaciones perinatales, ¿cuál es un indicador mayor de riesgo neurológico en el niño?",["La gran prematuridad (nacimiento antes de las 32 semanas cumplidas)","Una macrosomía fetal (peso elevado al nacer)","Una ictericia neonatal fisiológica moderada","Una puntuación de Apgar de 10 al quinto minuto"],["La gran prematuridad expone a lesiones cerebrales (hemorragia intraventricular, leucomalacia periventricular); la asfixia perinatal y las infecciones congénitas (TORCH) son otros indicadores de riesgo neurológico.","Falso: la macrosomía expone a un riesgo obstétrico (distocia de hombros), no a un riesgo neurológico central comparable a la gran prematuridad.","Falso: solo la ictericia nuclear (bilirrubina muy elevada no tratada) es neurotóxica; la ictericia fisiológica moderada no es un indicador de riesgo.","Falso: un Apgar de 10 traduce una buena adaptación neonatal y es al contrario tranquilizador; es un Apgar bajo y prolongado el que preocupa."]],
  "154": ["¿Qué distingue un tumor maligno de un tumor benigno?",["El tumor maligno invade los tejidos vecinos y metastatiza a distancia","El tumor benigno es siempre más voluminoso que el maligno","El tumor maligno está bien encapsulado y desplaza los tejidos","El tumor benigno presenta numerosas mitosis atípicas"],["Las células malignas franquean la membrana basal, invaden los tejidos vecinos, alcanzan los vasos y metastatizan; el tumor benigno crece localmente, desplazando los tejidos sin invadirlos ni diseminarse.","Falso: el tamaño no distingue a ambos; un tumor benigno (mioma, lipoma) puede ser voluminoso y uno maligno puede ser de pequeño tamaño.","Falso: es el tumor benigno el que suele estar encapsulado y desplaza los tejidos; el maligno está mal delimitado y es infiltrante.","Falso: las mitosis numerosas y atípicas caracterizan la malignidad; el tumor benigno tiene pocas mitosis, regulares."]],
  "155": ["Entre estas características («hallmarks») de las células cancerosas, ¿cuál es correcta?",["Escapan a la apoptosis y tienen replicación ilimitada por la telomerasa","Dependen estrictamente de las señales de crecimiento externas","Siguen siendo sensibles a las señales inhibidoras del crecimiento","Inhiben la angiogénesis y permanecen poco vascularizadas"],["Las células cancerosas evitan la apoptosis y reactivan la telomerasa (replicación ilimitada), entre los demás hallmarks: angiogénesis, invasión, inestabilidad genómica y autosuficiencia en señales de crecimiento.","Falso: un hallmark es al contrario la autosuficiencia en señales de crecimiento (autonomía proliferativa), no la dependencia de los factores externos.","Falso: las células cancerosas se vuelven insensibles a las señales antiproliferativas (pérdida de Rb/p53), ya no responden a ellas.","Falso: INDUCEN la angiogénesis (secreción de VEGF/FGF) para vascularizarse y crecer más allá de unos milímetros."]],
  "156": ["En nomenclatura oncológica, ¿cómo se denomina un tumor maligno de origen epitelial y un tumor maligno de origen conjuntivo?",["Carcinoma (epitelial) y sarcoma (conjuntivo)","Sarcoma (epitelial) y carcinoma (conjuntivo)","Linfoma (epitelial) y leucemia (conjuntivo)","Adenoma (epitelial maligno) y mioma (conjuntivo maligno)"],["El sufijo -carcinoma designa un tumor maligno epitelial; -sarcoma, un tumor maligno del tejido conjuntivo (el sufijo -oma designa generalmente un tumor benigno).","Es lo inverso: carcinoma = epitelial, sarcoma = conjuntivo.","El linfoma y la leucemia son neoplasias hematológicas, no epiteliales ni conjuntivas.","El adenoma y el mioma son al contrario tumores benignos (-oma)."]],
  "157": ["¿Cómo se define un síndrome paraneoplásico?",["Manifestaciones a distancia del tumor, independientes de toda metástasis","Síntomas ligados a la compresión de un órgano por el tumor","Síntomas debidos a la destrucción de un órgano por las metástasis","Síntomas provocados por la toxicidad directa de la quimioterapia"],["El síndrome paraneoplásico agrupa manifestaciones (endocrinas, neuromusculares, cutáneas) que aparecen a distancia del tumor, independientemente de toda metástasis, por secreción ectópica de sustancias o por mecanismo autoinmune.","Falso: la compresión de un órgano por la masa tumoral es un efecto local (síndrome de masa), distinto del síndrome paraneoplásico.","Falso: el síndrome paraneoplásico es precisamente INDEPENDIENTE de las metástasis; es por definición otro mecanismo.","Falso: los efectos adversos del tratamiento no corresponden al síndrome paraneoplásico, que está ligado al tumor en sí."]],
  "158": ["¿Qué agrupa el «síndrome constitucional» (síntomas B) del paciente con cáncer?",["Astenia, anorexia y adelgazamiento, con fiebre y sudoración nocturna","Poliuria, polidipsia y polifagia con aumento de peso","Poliartralgias, mialgias y rigidez matutina prolongada","Edemas de los miembros, disnea y aumento rápido de peso"],["El síndrome constitucional asocia astenia, anorexia, adelgazamiento, fiebre y sudoración nocturna, ligado al hipercatabolismo y a los pirógenos endógenos; en oncohematología se habla de «síntomas B».","Falso: esa tríada es la de la diabetes descompensada; el síndrome constitucional comporta al contrario un adelgazamiento.","Falso: esos signos orientan hacia una afectación reumatológica o un síndrome paraneoplásico articular, no hacia el síndrome constitucional.","Falso: esos signos evocan una retención hidrosalina (insuficiencia cardiaca); el síndrome constitucional comporta una pérdida de peso."]],
  "159": ["¿Cuáles son las principales vías de diseminación de las metástasis?",["Las vías hematógena, linfática y transcelómica (serosas)","Las vías hematógena, linfática y neurógena (a lo largo de los nervios)","Las vías hematógena, linfática y por contigüidad de un punto a otro","Las vías hematógena, linfática y canalicular (a lo largo de los conductos)"],["Las tres grandes vías son la hematógena (sangre), la linfática (ganglios) y la transcelómica (siembra en pleura, peritoneo, pericardio); el tropismo explica los sitios preferentes (mama → hueso).","Falso: la tercera gran vía es la transcelómica (serosas), no la neurógena; la infiltración perineural es una extensión local, no una vía clásica de metástasis a distancia.","Falso: la contigüidad define la invasión LOCAL (extensión directa), no una metástasis; la tercera vía de diseminación a distancia es la transcelómica.","Falso: la propagación canalicular sigue siendo un modo de extensión local (p. ej. carcinoma in situ); la tercera vía de metástasis es la transcelómica (serosas)."]],
  "160": ["¿Cuál es el tumor cerebral primario más frecuente y más agresivo en el adulto?",["El glioblastoma (glioma de alto grado)","El meduloblastoma (tumor de la fosa posterior)","El meningioma (tumor de las envolturas meníngeas)","El adenoma hipofisario (tumor de la silla turca)"],["En el adulto, los gliomas son los tumores primarios más frecuentes del SNC, y el glioblastoma (grado IV) es su forma más agresiva.","Falso: el meduloblastoma predomina en el NIÑO (cerebelo/fosa posterior), no en el adulto.","Falso: el meningioma, frecuente en el adulto, es la mayoría de las veces benigno y de evolución lenta, por lo que no es el más agresivo.","Falso: el adenoma hipofisario es habitualmente benigno y se manifiesta sobre todo por signos endocrinos o compresivos."]],
  "161": ["Respecto a las metástasis cerebrales, ¿qué proposición es correcta?",["Más frecuentes que los tumores primarios, proceden sobre todo del pulmón, de la mama y del melanoma","Más raras que los tumores primarios, proceden sobre todo del pulmón, de la mama y del melanoma","Más frecuentes que los tumores primarios, proceden sobre todo de la próstata y del colon","Más frecuentes que los tumores primarios, se localizan sobre todo en la sustancia blanca profunda"],["Las metástasis cerebrales son más frecuentes que los tumores primarios del SNC; el pulmón, la mama y el melanoma (y el riñón) son sus principales fuentes, con afectación de la unión corticosubcortical.","Falso en la frecuencia: las metástasis cerebrales son MÁS frecuentes que los tumores primarios del SNC, aunque el pulmón, la mama y el melanoma son efectivamente sus fuentes principales.","Falso en el origen: la próstata y el colon metastatizan raramente al cerebro; las fuentes principales son pulmón, mama, melanoma y riñón.","Falso en la localización: las metástasis cerebrales se localizan preferentemente en la unión corticosubcortical, donde el calibre vascular disminuye."]],
  "162": ["¿Cómo se maneja en primera intención el edema cerebral ligado al efecto de masa de un tumor?",["Con corticoides (dexametasona), reservando la cirugía descompresiva para los casos graves","Con manitol osmótico a largo plazo, pues la dexametasona es inútil aquí","Con una derivación ventricular desde el principio, pues los corticoides son ineficaces","Con una radioterapia urgente, que hace regresar el edema de inmediato"],["La dexametasona reduce el edema peritumoral (vasogénico); en caso de hipertensión intracraneal amenazante, una cirugía descompresiva evita la herniación.","Falso: el manitol es un tratamiento de apoyo puntual de la HTIC aguda, pero el tratamiento de fondo del edema peritumoral se basa en los corticoides.","Falso: la derivación trata la hidrocefalia obstructiva, no el edema vasogénico; el tratamiento de primera intención sigue siendo los corticoides.","Falso: la radioterapia actúa sobre el tumor a medio plazo e incluso puede agravar transitoriamente el edema; en agudo se usan los corticoides."]],
  "163": ["¿Qué significa la clasificación TNM utilizada en oncología?",["T = extensión del tumor primario, N = afectación ganglionar, M = metástasis a distancia","T = extensión del tumor, N = número de tumores, M = grado de malignidad","T = tipo histológico, N = afectación ganglionar, M = presencia de metástasis","T = extensión del tumor, N = grado de necrosis, M = presencia de metástasis"],["El TNM estadifica los tumores sólidos: T (tamaño/extensión), N (ganglios regionales, nodes), M (metástasis), con finalidad pronóstica y terapéutica.","Falso: N designa la afectación ganglionar (nodes) y M las metástasis; el grado de malignidad es un dato distinto del TNM.","Falso: T codifica la extensión/tamaño del tumor primario, no su tipo histológico, que corresponde al análisis anatomopatológico.","Falso: N corresponde a la afectación ganglionar (nodes), no a la necrosis tumoral."]],
  "164": ["¿Cómo caracteriza el curso el proceso de envejecimiento individual?",["Universal, irreversible, continuo, intrínseco y heterogéneo","Universal, irreversible, continuo, intrínseco y homogéneo","Universal, reversible, continuo, intrínseco y heterogéneo","Universal, irreversible, discontinuo, extrínseco y heterogéneo"],["El envejecimiento es universal e intrínseco, continuo e irreversible, pero heterogéneo: cada órgano envejece a su propio ritmo, de ahí una fuerte variabilidad interindividual.","Falso en un punto: el envejecimiento es heterogéneo (órganos e individuos envejecen a ritmos diferentes), y no homogéneo.","Falso en un punto: el envejecimiento es irreversible; puede ralentizarse pero no invertirse.","Falso en dos puntos: el envejecimiento es continuo (y no a saltos) y ante todo intrínseco, aunque el entorno lo modula."]],
  "165": ["¿Qué es la sarcopenia y en qué se diferencia de la atrofia muscular?",["Una pérdida de masa muscular ligada al envejecimiento, independiente de la inactividad","Una pérdida de masa muscular ligada a la inmovilización prolongada","Una pérdida de masa muscular ligada a un hipercatabolismo patológico","Una pérdida de densidad mineral ósea ligada al envejecimiento"],["La sarcopenia es la pérdida de masa y de fuerza musculares asociada a la edad, elemento central del modelo de fragilidad; se distingue de la atrofia ligada a la inactividad, la desnutrición o el hipercatabolismo.","Falso: la pérdida muscular ligada a la inmovilización o al decúbito define la atrofia por desuso, no la sarcopenia, que está ligada a la edad.","Falso: la fusión muscular de un hipercatabolismo (caquexia, sepsis, neoplasia) es una atrofia patológica, distinta de la sarcopenia ligada a la edad.","Falso: la pérdida de densidad mineral ósea define la osteoporosis, no la sarcopenia, que afecta al músculo."]],
  "166": ["¿Cómo evoluciona la composición corporal con el envejecimiento?",["Descenso de la masa magra y aumento de la masa grasa","Aumento de la masa magra y descenso de la masa grasa","Descenso de la masa grasa y aumento del agua total","Aumento de la masa magra y aumento del agua total"],["El sujeto mayor pierde masa muscular (sarcopenia) y agua corporal total mientras la masa grasa aumenta, del orden del 15 % en el joven a más del 30 % a los 75 años.","Falso: es lo inverso, la masa magra disminuye y la masa grasa aumenta con la edad.","Falso: la masa grasa aumenta y el agua corporal total disminuye en el sujeto mayor.","Falso: la masa magra y el agua total disminuyen ambas con el envejecimiento."]],
  "167": ["¿Cuál es el cambio fundamental del riñón ligado al envejecimiento?",["La reducción de la filtración glomerular","Un aumento de la filtración glomerular","Una mejora de la capacidad de concentrar la orina","Un aumento de la hidroxilación renal de la vitamina D"],["El cambio renal fundamental es el descenso del filtrado glomerular (rarefacción de los glomérulos ya a partir de los 50 años, pérdida de aclaramiento de creatinina de 7,5-10 ml por década), con un riesgo aumentado de sobredosificación medicamentosa.","La filtración glomerular DISMINUYE con la edad, no aumenta.","La capacidad de concentración urinaria disminuye, lo que aumenta las pérdidas hídricas.","La activación renal de la vitamina D DISMINUYE, lo que reduce la absorción del calcio."]]
});
